-- Server bill review and durable explicitly confirmed unsent financial requests.
-- Transport, receipts and money postings remain disabled until the next migration.

CREATE TABLE _dg_native_bill_origins(bill_id text PRIMARY KEY REFERENCES restaurant_bills(id),order_id text NOT NULL UNIQUE REFERENCES restaurant_orders(id),party_id text NOT NULL REFERENCES dining_parties(id),runtime_id text NOT NULL,action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),created_at text NOT NULL);
CREATE TABLE _dg_native_bill_revisions(bill_id text NOT NULL REFERENCES restaurant_bills(id),version bigint NOT NULL,action_id text NOT NULL REFERENCES _dg_native_dining_actions(id),row_hash text NOT NULL,created_at text NOT NULL,PRIMARY KEY(bill_id,version));
CREATE TABLE _dg_native_bill_quote_origins(quote_id text PRIMARY KEY REFERENCES restaurant_financial_quotes(id),action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),runtime_id text NOT NULL,actor_meta jsonb NOT NULL,confirmation_hash text NOT NULL CHECK(confirmation_hash~'^[a-f0-9]{64}$'),payload_hash text NOT NULL,created_at text NOT NULL,expires_at text NOT NULL);
CREATE TABLE _dg_native_bill_operation_origins(operation_id text PRIMARY KEY REFERENCES restaurant_financial_operations(id),action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),quote_id text NOT NULL UNIQUE REFERENCES restaurant_financial_quotes(id),runtime_id text NOT NULL,request_hash text NOT NULL,created_at text NOT NULL);
CREATE TABLE _dg_native_bill_results(action_id text PRIMARY KEY REFERENCES _dg_native_dining_actions(id),restaurant_id text NOT NULL REFERENCES restaurants(id),bill_id text REFERENCES restaurant_bills(id),party_access_version bigint,created_at text NOT NULL);
CREATE TABLE _dg_native_bill_config_revisions(restaurant_id text NOT NULL REFERENCES restaurants(id),version bigint NOT NULL,action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),provider_id text NOT NULL,enabled bigint NOT NULL,merchant_id text NOT NULL,scenario text NOT NULL,created_at text NOT NULL,PRIMARY KEY(restaurant_id,version));
CREATE TABLE _dg_native_bill_worker_leases(lease_token text PRIMARY KEY,operation_id text NOT NULL REFERENCES restaurant_financial_operations(id),mode text NOT NULL CHECK(mode IN('send','query','close','simulate')),request_hash text NOT NULL,runtime_id text NOT NULL,action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),created_at text NOT NULL,expires_at text NOT NULL);
CREATE TABLE _dg_native_bill_receipt_origins(event_id text PRIMARY KEY REFERENCES restaurant_financial_receipts(event_id),action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),runtime_id text NOT NULL,request_hash text NOT NULL,receipt_hash text NOT NULL,ingress text NOT NULL CHECK(ingress IN('worker','callback','mock_fixture')),created_at text NOT NULL);
CREATE TABLE _dg_native_bill_posting_origins(posting_id text PRIMARY KEY REFERENCES restaurant_financial_postings(id),event_id text NOT NULL UNIQUE REFERENCES restaurant_financial_receipts(event_id),operation_id text NOT NULL UNIQUE REFERENCES restaurant_financial_operations(id),runtime_id text NOT NULL,action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id));
CREATE TABLE _dg_native_bill_mock_revisions(operation_id text NOT NULL REFERENCES mock_financial_operations(operation_id),sequence bigint NOT NULL,action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),row_hash text NOT NULL,created_at text NOT NULL,PRIMARY KEY(operation_id,sequence));
CREATE TABLE _dg_native_bill_action_origins(action_id text PRIMARY KEY REFERENCES _dg_native_dining_actions(id),operation_id text NOT NULL REFERENCES restaurant_financial_operations(id),mode text NOT NULL CHECK(mode IN('query','close','simulate')),actor_meta jsonb NOT NULL,created_at text NOT NULL);
CREATE TABLE _dg_native_bill_receipt_failures(event_id text PRIMARY KEY REFERENCES restaurant_financial_receipts(event_id),sqlstate text NOT NULL CHECK(length(sqlstate)=5),failure_site text NOT NULL,created_at text NOT NULL);
DO $bill_immutable$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['_dg_native_bill_origins','_dg_native_bill_revisions','_dg_native_bill_quote_origins','_dg_native_bill_operation_origins','_dg_native_bill_results','_dg_native_bill_config_revisions','_dg_native_bill_worker_leases','_dg_native_bill_receipt_origins','_dg_native_bill_posting_origins','_dg_native_bill_mock_revisions','_dg_native_bill_action_origins','_dg_native_bill_receipt_failures'] LOOP EXECUTE format('CREATE TRIGGER native_bill_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION dg_native_append_only()',table_value);END LOOP;END;$bill_immutable$;

CREATE FUNCTION dg_native_bill_error(code_value text) RETURNS void LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$ BEGIN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='DGBILL:'||code_value;END;$dg$;
CREATE FUNCTION dg_native_bill_manager(meta jsonb) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT meta->>'actorType'='staff' AND dg_native_dining_clock_authority(meta->>'actorId',meta->>'restaurantId',(meta->>'actorEpoch')::bigint,(meta->>'grantVersion')::bigint) AND EXISTS(SELECT 1 FROM memberships member WHERE member.user_id=meta->>'actorId' AND(member.role='admin' OR EXISTS(SELECT 1 FROM restaurant_staff staff WHERE staff.restaurant_id=meta->>'restaurantId' AND staff.user_id=member.user_id AND staff.role='manager' AND staff.enabled=1 AND staff.version=(meta->>'grantVersion')::bigint AND(staff.expires_at IS NULL OR staff.expires_at>dg_native_dining_now()))))
$dg$;

CREATE FUNCTION dg_native_bill_context(kind_value text,target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL,csrf_value text DEFAULT NULL,focus_value bigint DEFAULT NULL,write_value boolean DEFAULT false,historical_value boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE order_value text;bill_value text;operation_value text;quote_value text;meta jsonb;p dining_parties%ROWTYPE;
BEGIN
 IF kind_value='restaurant' THEN RETURN dg_native_dining_context('restaurant',target,session_value,token_value,csrf_value,focus_value,write_value);END IF;
 IF kind_value='party' THEN meta:=dg_native_order_context('party',target,session_value,token_value,csrf_value,focus_value,write_value);RETURN meta||jsonb_build_object('billId',NULL,'operationId',NULL,'quoteId',NULL);END IF;
 IF kind_value='order' THEN order_value:=target;SELECT bill_id INTO bill_value FROM _dg_native_bill_origins WHERE order_id=target;
 ELSIF kind_value='bill' THEN SELECT order_id,bill_id INTO order_value,bill_value FROM _dg_native_bill_origins WHERE bill_id=target;
 ELSIF kind_value='quote' THEN quote_value:=target;SELECT fixed.order_id,fixed.bill_id INTO order_value,bill_value FROM restaurant_financial_quotes quote JOIN _dg_native_bill_quote_origins origin ON origin.quote_id=quote.id JOIN _dg_native_bill_origins fixed ON fixed.bill_id=quote.bill_id WHERE quote.id=target;
 ELSIF kind_value='operation' THEN operation_value:=target;SELECT fixed.order_id,fixed.bill_id INTO order_value,bill_value FROM restaurant_financial_operations operation JOIN _dg_native_bill_operation_origins origin ON origin.operation_id=operation.id JOIN _dg_native_bill_origins fixed ON fixed.bill_id=operation.bill_id WHERE operation.id=target;ELSE PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
 IF order_value IS NULL THEN PERFORM dg_native_bill_error('NOT_FOUND');END IF;
 meta:=dg_native_order_context('order',order_value,session_value,token_value,csrf_value,focus_value,write_value AND NOT(historical_value AND session_value IS NULL));
 IF write_value AND historical_value AND session_value IS NULL THEN
  meta:=meta||dg_native_dining_context('restaurant',meta->>'restaurantId',NULL,NULL,NULL,NULL,true);SELECT * INTO p FROM dining_parties WHERE id=(SELECT party_id FROM restaurant_orders WHERE id=order_value) FOR UPDATE;meta:=meta||jsonb_build_object('orderId',order_value,'partyId',p.id,'partyVersion',p.version,'partyAccessVersion',p.access_version);
 END IF;
 RETURN meta||jsonb_build_object('billId',bill_value,'operationId',operation_value,'quoteId',quote_value);
END;$dg$;

CREATE FUNCTION dg_native_bill_connection(target text,manager_value boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE config restaurant_payment_configs%ROWTYPE;configured_value boolean;
BEGIN SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=target;configured_value:=coalesce(config.enabled=1 AND config.provider_id='mock-payments',false);RETURN jsonb_build_object('restaurantId',target,'providerId',config.provider_id,'enabled',coalesce(config.enabled=1,false),'scenario',CASE WHEN config.restaurant_id IS NOT NULL THEN config.scenario END,'version',coalesce(config.version,0),'configured',configured_value,'simulated',coalesce(config.provider_id='mock-payments',false),'mockAllowed',true,'canManage',manager_value,'notice',CASE WHEN configured_value THEN '明确本地模拟收银与退款，没有真实资金往来。' WHEN config.provider_id='external-payments' THEN '真实支付尚未接通，不能回退为模拟成功。' ELSE '请经理配置明确的本地模拟支付连接，或接入并验证真实支付。' END);END;$dg$;

CREATE FUNCTION dg_native_bill_totals(target text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;paid bigint;refunded bigint;reserved bigint;payments bigint;refunds bigint;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;SELECT coalesce(sum(amount_minor) FILTER(WHERE kind='payment'),0),coalesce(sum(amount_minor) FILTER(WHERE kind='refund'),0) INTO paid,refunded FROM restaurant_financial_postings WHERE bill_id=b.id;
 SELECT count(*) FILTER(WHERE kind='payment'),count(*) FILTER(WHERE kind='refund'),coalesce(sum(amount_minor) FILTER(WHERE kind='refund' AND NOT EXISTS(SELECT 1 FROM restaurant_financial_postings posting WHERE posting.operation_id=operation.id)),0) INTO payments,refunds,reserved FROM restaurant_financial_operations operation WHERE bill_id=b.id AND status IN('queued','submitting','pending','unknown','needs_attention');
 RETURN jsonb_build_object('paid',paid,'refunded',refunded,'reserved',reserved,'activePayments',payments,'activeRefunds',refunds,'balance',b.amount_minor-paid);
END;$dg$;

CREATE FUNCTION dg_native_bill_refundable(payment_value text,except_value text DEFAULT '') RETURNS bigint LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT CASE WHEN payment.kind='payment' AND EXISTS(SELECT 1 FROM restaurant_financial_postings posting WHERE posting.operation_id=payment.id AND posting.kind='payment') THEN greatest(0,payment.amount_minor-(SELECT coalesce(sum(refund.amount_minor),0) FROM restaurant_financial_operations refund WHERE refund.parent_payment_id=payment.id AND refund.id<>except_value AND(refund.status IN('queued','submitting','pending','unknown','needs_attention') OR EXISTS(SELECT 1 FROM restaurant_financial_postings posting WHERE posting.operation_id=refund.id)))) ELSE 0 END FROM restaurant_financial_operations payment WHERE payment.id=payment_value
$dg$;

CREATE FUNCTION dg_native_bill_lines(order_value text) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT coalesce(jsonb_agg(jsonb_build_object('lineId',line.id,'itemName',line.item_name,'skuName',line.sku_name,'unitPriceMinor',line.unit_price_minor,'quantity',line.quantity-line.cancelled_quantity,'subtotalMinor',(line.quantity-line.cancelled_quantity)*line.unit_price_minor) ORDER BY line.created_at,line.id),'[]') FROM restaurant_order_lines line JOIN _dg_native_order_line_origins fixed ON fixed.line_id=line.id WHERE line.order_id=order_value AND line.quantity>line.cancelled_quantity
$dg$;

CREATE FUNCTION dg_native_bill_payment_reason(order_value text,meta jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE o restaurant_orders%ROWTYPE;p dining_parties%ROWTYPE;
BEGIN SELECT * INTO o FROM restaurant_orders WHERE id=order_value;SELECT * INTO p FROM dining_parties WHERE id=o.party_id;
 IF p.status<>'seated' OR NOT EXISTS(SELECT 1 FROM dining_occupancies WHERE party_id=p.id AND state='seated') THEN RETURN '请先核对本次实际入座与当前桌位。';END IF;
 IF o.pending_change_id IS NOT NULL OR o.control_mode<>'automatic' OR EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=o.id AND(dispatch.status IN('queued','submitting','submitted','unknown') OR dispatch.error_code='POS_RECONCILIATION_REQUIRED')) THEN RETURN '订单仍有变更、未知派单或人工核对，请先确认实际接单明细。';END IF;
 IF meta->>'actorType'='guest' AND NOT dg_native_order_source(meta,p.id) THEN RETURN '本次会话、发问人、选择或就餐归属已经变化。';END IF;RETURN NULL;
END;$dg$;

CREATE FUNCTION dg_native_bill_event(action_value text,bill_value text,operation_value text,message_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE id_value text:=gen_random_uuid()::text;a _dg_native_dining_actions%ROWTYPE;
BEGIN SELECT * INTO a FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(a.id,'restaurant_financial_events',id_value);INSERT INTO restaurant_financial_events VALUES(id_value,bill_value,operation_value,a.actor_id,a.kind,jsonb_build_object('message',message_value)::text,a.created_at);END;$dg$;

CREATE FUNCTION dg_native_bill_state(target text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;t jsonb;status_value text;attention_value text;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;t:=dg_native_bill_totals(b.id);
 IF EXISTS(SELECT 1 FROM restaurant_financial_operations WHERE bill_id=b.id AND error_code='FINANCIAL_RECONCILIATION_REQUIRED') THEN status_value:='needs_attention';attention_value:='可信资金回执的本地投影仍待核对，请经理查询原事实。';
 ELSIF EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=o.id AND dispatch.error_code='POS_RECONCILIATION_REQUIRED') THEN status_value:='needs_attention';attention_value:='订单存在矛盾POS回执，资金事实保留，实际接单须经理核对。';
 ELSIF EXISTS(SELECT 1 FROM restaurant_financial_operations payment WHERE payment.bill_id=b.id AND payment.kind='payment' AND(SELECT coalesce(sum(posting.amount_minor),0) FROM restaurant_financial_postings posting JOIN restaurant_financial_operations refund ON refund.id=posting.operation_id WHERE refund.parent_payment_id=payment.id AND posting.kind='refund')>payment.amount_minor) THEN status_value:='needs_attention';attention_value:='已核实的退款超过原收款，原事实全部保留，请经理核对。';
 ELSIF(t->>'paid')::bigint-(t->>'refunded')::bigint>b.amount_minor THEN status_value:='needs_attention';attention_value:='存在已核实超付，请经理核对原收款并按权限处理退款。';
 ELSIF o.content_version<>b.order_content_version AND((t->>'paid')::bigint>0 OR(t->>'activePayments')::bigint>0) THEN status_value:='needs_attention';attention_value:='实际接单明细与原账单不一致，原资金事实保留，禁止继续按旧金额收款。';
 ELSIF(t->>'paid')::bigint>=b.amount_minor AND(t->>'activePayments')::bigint>0 THEN status_value:='needs_attention';attention_value:='已有足额资金事实但其他支付尝试仍未核实，请查询或关闭原尝试。';
 ELSIF(t->>'activePayments')::bigint>0 THEN status_value:='payment_pending';
 ELSIF b.amount_minor=0 AND(t->>'paid')::bigint=0 THEN status_value:='void';
 ELSIF(t->>'paid')::bigint>=b.amount_minor THEN status_value:=CASE WHEN(t->>'refunded')::bigint>=(t->>'paid')::bigint THEN 'refunded' WHEN(t->>'refunded')::bigint>0 THEN 'partially_refunded' ELSE 'paid' END;
 ELSE status_value:='open';END IF;
 RETURN jsonb_build_object('status',status_value,'attentionReason',attention_value,'settled',status_value IN('paid','partially_refunded','refunded','void'));
END;$dg$;

CREATE FUNCTION dg_native_bill_order_fulfilled(order_value text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT current_order.pending_change_id IS NULL AND EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=current_order.id AND bill.status IN('paid','partially_refunded','refunded','void') AND bill.attention_reason IS NULL AND bill.order_content_version=current_order.content_version AND NOT EXISTS(SELECT 1 FROM restaurant_financial_operations operation WHERE operation.bill_id=bill.id AND(operation.status IN('queued','submitting','pending','unknown','needs_attention') OR operation.error_code='FINANCIAL_RECONCILIATION_REQUIRED'))) AND NOT EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=current_order.id AND(dispatch.status IN('queued','submitting','submitted','unknown') OR dispatch.error_code='POS_RECONCILIATION_REQUIRED')) AND NOT EXISTS(SELECT 1 FROM restaurant_order_lines line LEFT JOIN restaurant_kitchen_tickets ticket ON ticket.line_id=line.id WHERE line.order_id=current_order.id AND(line.quantity>line.cancelled_quantity AND(ticket.id IS NULL OR ticket.served_quantity<>line.quantity-line.cancelled_quantity) OR coalesce(ticket.pending_cancel_quantity,0)>0)) FROM restaurant_orders current_order WHERE current_order.id=order_value
$dg$;

CREATE FUNCTION dg_native_bill_refresh(action_value text,target text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;state_value jsonb;created text;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;state_value:=dg_native_bill_state(b.id);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_bills',b.id);UPDATE restaurant_bills SET status=state_value->>'status',attention_reason=state_value->>'attentionReason',settled_at=CASE WHEN settled_at IS NULL AND(state_value->>'settled')::boolean THEN created ELSE settled_at END,version=version+1,updated_at=created WHERE id=b.id;
 IF(state_value->>'settled')::boolean AND EXISTS(SELECT 1 FROM restaurant_orders WHERE id=b.order_id AND settlement_status<>'settled') THEN PERFORM dg_native_dining_effect(action_value,'restaurant_orders',b.order_id);UPDATE restaurant_orders SET settlement_status='settled',status=CASE WHEN dg_native_bill_order_fulfilled(id) AND status<>'cancelled' THEN 'closed' ELSE dg_native_order_status(id) END,version=version+1,updated_at=created WHERE id=b.order_id;END IF;
END;$dg$;

CREATE FUNCTION dg_native_bill_party_finishable(target text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT NOT EXISTS(SELECT 1 FROM restaurant_orders current_order WHERE current_order.party_id=target AND NOT(coalesce(dg_native_bill_order_fulfilled(current_order.id),false) OR current_order.status='cancelled' AND current_order.pending_change_id IS NULL AND NOT EXISTS(SELECT 1 FROM restaurant_order_lines line WHERE line.order_id=current_order.id AND line.quantity>line.cancelled_quantity) AND NOT EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=current_order.id AND(dispatch.attempts<>0 OR dispatch.status<>'cancelled')) AND NOT EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=current_order.id)))
$dg$;

CREATE FUNCTION dg_native_bill_quote_reason(target text,reader_meta jsonb DEFAULT NULL,queued_value boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE q restaurant_financial_quotes%ROWTYPE;fixed _dg_native_bill_quote_origins%ROWTYPE;b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;p dining_parties%ROWTYPE;r restaurants%ROWTYPE;config restaurant_payment_configs%ROWTYPE;snapshot jsonb;totals jsonb;parent restaurant_financial_operations%ROWTYPE;reason_value text;
BEGIN
 SELECT * INTO q FROM restaurant_financial_quotes WHERE id=target;SELECT * INTO fixed FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;IF q.id IS NULL OR fixed.quote_id IS NULL THEN RETURN '审阅不存在。';END IF;snapshot:=q.payload::jsonb;SELECT * INTO b FROM restaurant_bills WHERE id=q.bill_id;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;SELECT * INTO p FROM dining_parties WHERE id=b.party_id;SELECT * INTO r FROM restaurants WHERE id=b.restaurant_id;SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=r.id;totals:=dg_native_bill_totals(b.id);
 IF reader_meta IS NOT NULL AND reader_meta-ARRAY['billId','operationId','quoteId','orderId','changeId','partyVersion','partyAccessVersion'] IS DISTINCT FROM fixed.actor_meta-ARRAY['billId','operationId','quoteId','orderId','changeId','partyVersion','partyAccessVersion'] THEN RETURN '原确认人、会话、发问人、选择或人员授权已经变化。';END IF;
 IF(q.status<>'current' AND NOT(queued_value AND q.status='consumed')) OR q.expires_at<=dg_native_dining_now() THEN RETURN '原审阅已到期、已使用或被替代，请重新核对。';END IF;
 IF NOT queued_value AND b.version<>(snapshot->>'billVersion')::bigint OR o.content_version<>(snapshot->>'orderContentVersion')::bigint OR b.order_content_version<>(snapshot->>'orderContentVersion')::bigint OR p.version<>(snapshot->>'partyVersion')::bigint OR p.access_version<>(snapshot->>'partyAccessVersion')::bigint OR r.version<>(snapshot->>'restaurantVersion')::bigint THEN RETURN '原账单、接单明细、就餐安排或归属已有新版本。';END IF;
 IF config.restaurant_id IS NULL OR config.provider_id<>'mock-payments' OR config.enabled<>1 OR config.version<>(snapshot->>'configVersion')::bigint OR config.merchant_id IS DISTINCT FROM snapshot->>'merchantId' THEN RETURN '原商户或支付连接已经变化，请重新核对。';END IF;
 IF q.kind='payment' THEN
  IF NOT dg_native_order_source(fixed.actor_meta,p.id) THEN RETURN '原顾客、人员或接待来源已失效。';END IF;reason_value:=dg_native_bill_payment_reason(o.id,fixed.actor_meta);IF reason_value IS NOT NULL THEN RETURN reason_value;END IF;
  IF NOT EXISTS(SELECT 1 FROM dining_occupancies WHERE party_id=p.id AND state='seated' AND id=snapshot->>'occupancyId') OR(totals->>'balance')::bigint<>(snapshot->>'amountMinor')::bigint OR(totals->>'balance')::bigint<=0 OR NOT queued_value AND(totals->>'activePayments')::bigint>0 THEN RETURN '当前桌位、未核实支付或剩余金额已变化，请核对原请求。';END IF;
 ELSE
  IF NOT dg_native_bill_manager(fixed.actor_meta) THEN RETURN '原退款经理授权已经失效，请由当前经理重新核对。';END IF;SELECT * INTO parent FROM restaurant_financial_operations WHERE id=q.parent_payment_id;
  IF parent.id IS NULL OR parent.bill_id<>b.id OR parent.kind<>'payment' OR NOT queued_value AND parent.version<>(snapshot->>'parentPaymentVersion')::bigint OR coalesce(dg_native_bill_refundable(parent.id,CASE WHEN queued_value THEN(SELECT id FROM restaurant_financial_operations WHERE quote_id=q.id) ELSE '' END),0)<(snapshot->>'amountMinor')::bigint OR EXISTS(SELECT 1 FROM restaurant_financial_operations WHERE bill_id=b.id AND error_code='FINANCIAL_RECONCILIATION_REQUIRED') THEN RETURN '原收款、可退余额或待核对资金事实已经变化。';END IF;
 END IF;RETURN NULL;
END;$dg$;

CREATE FUNCTION dg_native_bill_quote_create(action_value text,bill_value text,kind_value text,amount_value bigint,reason_value text,parent_value text,meta jsonb,input jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;p dining_parties%ROWTYPE;r restaurants%ROWTYPE;config restaurant_payment_configs%ROWTYPE;parent restaurant_financial_operations%ROWTYPE;quote_value text:=input->>'_quoteId';created text;expires text;snapshot jsonb;previous_value text;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=bill_value;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;SELECT * INTO p FROM dining_parties WHERE id=b.party_id;SELECT * INTO r FROM restaurants WHERE id=b.restaurant_id;SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=r.id;SELECT * INTO parent FROM restaurant_financial_operations WHERE id=parent_value;
 IF config.restaurant_id IS NULL OR config.enabled<>1 OR config.provider_id<>'mock-payments' THEN PERFORM dg_native_bill_error('PAYMENT_NOT_CONFIGURED');END IF;IF quote_value IS NULL OR quote_value!~'^[a-f0-9-]{36}$' OR input->>'_confirmationHash' IS NULL OR input->>'_confirmationHash'!~'^[a-f0-9]{64}$' OR amount_value NOT BETWEEN 1 AND 100000000 THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
 SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;expires:=dg_native_people_iso(created::timestamptz+interval '120 seconds');snapshot:=jsonb_build_object('id',quote_value,'kind',kind_value,'billId',b.id,'billVersion',b.version,'orderId',o.id,'orderContentVersion',o.content_version,'restaurantId',r.id,'restaurantVersion',r.version,'partyId',p.id,'partyVersion',p.version,'partyAccessVersion',p.access_version,'occupancyId',(SELECT id FROM dining_occupancies WHERE party_id=p.id AND state='seated'),'configVersion',config.version,'merchantId',config.merchant_id,'parentPaymentId',parent_value,'parentPaymentVersion',parent.version,'amountMinor',amount_value,'reason',reason_value,'lines',b.snapshot::jsonb,'expiresAt',expires);
 FOR previous_value IN SELECT id FROM restaurant_financial_quotes WHERE bill_id=b.id AND kind=kind_value AND status='current' LOOP PERFORM dg_native_dining_effect(action_value,'restaurant_financial_quotes',previous_value);UPDATE restaurant_financial_quotes SET status='superseded' WHERE id=previous_value;END LOOP;
 PERFORM dg_native_dining_effect(action_value,'restaurant_financial_quotes',quote_value);INSERT INTO restaurant_financial_quotes VALUES(quote_value,b.id,kind_value,parent_value,dg_native_office_hash(snapshot),snapshot::text,meta->>'actorId',meta->>'sessionId',(meta->>'focusVersion')::bigint,'current',expires,created);INSERT INTO _dg_native_bill_quote_origins VALUES(quote_value,action_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),meta,input->>'_confirmationHash',dg_native_office_hash(snapshot),created,expires);RETURN quote_value;
END;$dg$;

CREATE FUNCTION dg_native_bill_apply(kind_value text,target text,action_value text,input jsonb,session_value text DEFAULT NULL,token_value text DEFAULT NULL,csrf_value text DEFAULT NULL,focus_value bigint DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;body jsonb:=input-ARRAY['focusVersion','selectionVersion'];action_id_value text;created text;bill_value text;quote_value text;operation_value text;lines_value jsonb;amount_value bigint;totals jsonb;reason_value text;payload jsonb;revision_value bigint;
 r restaurants%ROWTYPE;p dining_parties%ROWTYPE;o restaurant_orders%ROWTYPE;b restaurant_bills%ROWTYPE;q restaurant_financial_quotes%ROWTYPE;fixed _dg_native_bill_quote_origins%ROWTYPE;config restaurant_payment_configs%ROWTYPE;parent restaurant_financial_operations%ROWTYPE;operation restaurant_financial_operations%ROWTYPE;
BEGIN
 IF action_value NOT IN('config','review','refund_review','confirm','withdraw') OR jsonb_typeof(input) IS DISTINCT FROM 'object' THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
 meta:=dg_native_bill_context(kind_value,target,session_value,token_value,csrf_value,focus_value,true,action_value IN('refund_review','confirm','withdraw'));PERFORM dg_native_order_input(meta,input);SELECT * INTO r FROM restaurants WHERE id=meta->>'restaurantId';
 IF action_value='config' THEN
  IF kind_value<>'restaurant' OR NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['version','providerId','enabled','scenario','confirmed']);
  IF body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(body->'enabled') IS DISTINCT FROM 'boolean' OR body->>'providerId' IS NULL OR body->>'providerId' NOT IN('mock-payments','external-payments') OR body->>'scenario' IS NULL OR body->>'scenario' NOT IN('normal','failed','response_lost','unresolved') THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
  IF body->>'providerId'='external-payments' AND body->'enabled'='true'::jsonb THEN PERFORM dg_native_bill_error('PAYMENT_PROVIDER_UNAVAILABLE');END IF;
  SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=r.id FOR UPDATE;IF dg_native_restaurant_integer(body->'version',0,9007199254740991)<>coalesce(config.version,0) THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;
  action_id_value:=dg_native_dining_action(meta,'bill_config','restaurant',r.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;revision_value:=coalesce(config.version,0)+1;PERFORM dg_native_dining_effect(action_id_value,'restaurant_payment_configs',r.id);
  IF config.restaurant_id IS NULL THEN INSERT INTO restaurant_payment_configs VALUES(r.id,body->>'providerId',CASE WHEN body->'enabled'='true'::jsonb THEN 1 ELSE 0 END,'mock-merchant:'||r.id,body->>'scenario',revision_value,created,created);
  ELSE UPDATE restaurant_payment_configs SET provider_id=body->>'providerId',enabled=CASE WHEN body->'enabled'='true'::jsonb THEN 1 ELSE 0 END,scenario=body->>'scenario',version=revision_value,updated_at=created WHERE restaurant_id=r.id;END IF;
  INSERT INTO _dg_native_bill_config_revisions VALUES(r.id,revision_value,action_id_value,body->>'providerId',CASE WHEN body->'enabled'='true'::jsonb THEN 1 ELSE 0 END,'mock-merchant:'||r.id,body->>'scenario',created);INSERT INTO _dg_native_bill_results VALUES(action_id_value,r.id,NULL,NULL,created);RETURN action_id_value;
 END IF;
 SELECT * INTO p FROM dining_parties WHERE id=meta->>'partyId';SELECT * INTO o FROM restaurant_orders WHERE id=meta->>'orderId' FOR UPDATE;SELECT * INTO b FROM restaurant_bills WHERE order_id=o.id FOR UPDATE;
 IF action_value='review' THEN
  IF kind_value<>'order' THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['orderVersion','billVersion','_quoteId','_confirmationHash']);
  IF dg_native_restaurant_integer(body->'orderVersion',1,9007199254740991)<>o.version OR dg_native_restaurant_integer(body->'billVersion',0,9007199254740991)<>coalesce(b.version,0) THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;
  reason_value:=dg_native_bill_payment_reason(o.id,meta);IF reason_value IS NOT NULL THEN PERFORM dg_native_bill_error('BILL_NOT_REVIEWABLE');END IF;
  IF b.id IS NOT NULL THEN totals:=dg_native_bill_totals(b.id);IF(totals->>'paid')::bigint>0 OR(totals->>'activePayments')::bigint>0 OR(totals->>'activeRefunds')::bigint>0 OR b.attention_reason IS NOT NULL THEN PERFORM dg_native_bill_error('FINANCIAL_PENDING');END IF;END IF;
  lines_value:=dg_native_bill_lines(o.id);SELECT coalesce(sum((value->>'subtotalMinor')::bigint),0) INTO amount_value FROM jsonb_array_elements(lines_value);IF amount_value NOT BETWEEN 0 AND 100000000 THEN PERFORM dg_native_bill_error('BILL_AMOUNT_INVALID');END IF;
  IF lines_value='[]'::jsonb AND o.status<>'cancelled' THEN PERFORM dg_native_bill_error('BILL_EMPTY');END IF;
  action_id_value:=dg_native_dining_action(meta,'bill_review','party',p.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;bill_value:=coalesce(b.id,gen_random_uuid()::text);PERFORM dg_native_dining_effect(action_id_value,'restaurant_bills',bill_value);
  IF b.id IS NULL THEN
   INSERT INTO restaurant_bills VALUES(bill_value,r.id,p.id,o.id,'B-'||substring(o.number FROM 3),1,o.content_version,amount_value,lines_value::text,'open',NULL,NULL,created,created);INSERT INTO _dg_native_bill_origins VALUES(bill_value,o.id,p.id,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),action_id_value,created);
  ELSE UPDATE restaurant_bills SET order_content_version=o.content_version,amount_minor=amount_value,snapshot=lines_value::text,version=version+1,status='open',attention_reason=NULL,updated_at=created WHERE id=bill_value;END IF;
  PERFORM dg_native_bill_refresh(action_id_value,bill_value);
  IF amount_value>0 THEN quote_value:=dg_native_bill_quote_create(action_id_value,bill_value,'payment',amount_value,'本次账单收银',NULL,meta,input);END IF;
  PERFORM dg_native_bill_event(action_id_value,bill_value,NULL,CASE WHEN amount_value=0 THEN '已核对本次有效明细，无待收金额；制作和就餐结束仍需分别核实。' ELSE '已生成原价账单审阅，明确确认仅建立收银请求。' END);
 ELSIF action_value='refund_review' THEN
  IF kind_value<>'bill' OR NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['billVersion','paymentId','amountMinor','reason','confirmed','_quoteId','_confirmationHash']);
  IF body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR length(trim(coalesce(body->>'reason',''))) NOT BETWEEN 3 AND 200 THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;IF dg_native_restaurant_integer(body->'billVersion',1,9007199254740991)<>b.version THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;
  SELECT * INTO parent FROM restaurant_financial_operations WHERE id=body->>'paymentId' AND bill_id=b.id AND kind='payment' FOR UPDATE;amount_value:=dg_native_restaurant_integer(body->'amountMinor',1,100000000);
  IF parent.id IS NULL OR coalesce(dg_native_bill_refundable(parent.id),0)<amount_value OR EXISTS(SELECT 1 FROM restaurant_financial_operations WHERE bill_id=b.id AND error_code='FINANCIAL_RECONCILIATION_REQUIRED') THEN PERFORM dg_native_bill_error('REFUND_UNAVAILABLE');END IF;
  action_id_value:=dg_native_dining_action(meta,'bill_refund_review','party',p.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;bill_value:=b.id;quote_value:=dg_native_bill_quote_create(action_id_value,bill_value,'refund',amount_value,trim(body->>'reason'),parent.id,meta,input);PERFORM dg_native_bill_event(action_id_value,bill_value,NULL,'经理已审阅原收款及当前可退额，尚未发送退款。');
 ELSIF action_value='confirm' THEN
  IF kind_value<>'quote' THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['quoteId','_confirmationHash','confirmed']);
  SELECT * INTO q FROM restaurant_financial_quotes WHERE id=target FOR UPDATE;SELECT * INTO fixed FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;
  IF body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR body->>'quoteId' IS DISTINCT FROM q.id OR body->>'_confirmationHash' IS DISTINCT FROM fixed.confirmation_hash THEN PERFORM dg_native_bill_error('BILL_CONFIRMATION_INVALID');END IF;
  reason_value:=dg_native_bill_quote_reason(q.id,meta);IF reason_value IS NOT NULL THEN PERFORM dg_native_bill_error('BILL_QUOTE_CHANGED');END IF;
  SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=r.id;SELECT * INTO parent FROM restaurant_financial_operations WHERE id=q.parent_payment_id;payload:=q.payload::jsonb;amount_value:=(payload->>'amountMinor')::bigint;operation_value:=gen_random_uuid()::text;bill_value:=b.id;
  action_id_value:=dg_native_dining_action(meta,'bill_confirm','party',p.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;
  payload:=jsonb_build_object('operationId',operation_value,'kind',q.kind,'restaurantId',r.id,'billId',b.id,'orderId',o.id,'merchantId',config.merchant_id,'amountMinor',amount_value,'currency','CNY','parentPaymentId',q.parent_payment_id,'parentRemoteTransactionId',parent.remote_transaction_id);
  PERFORM dg_native_dining_effect(action_id_value,'restaurant_financial_operations',operation_value);
  INSERT INTO restaurant_financial_operations(id,bill_id,kind,parent_payment_id,quote_id,status,version,amount_minor,provider_id,merchant_id,config_version,config_snapshot,request_payload,request_hash,reason,simulated,actor_id,session_id,focus_version,party_access_version,created_at,updated_at)
  VALUES(operation_value,b.id,q.kind,q.parent_payment_id,q.id,'queued',1,amount_value,config.provider_id,config.merchant_id,config.version,to_jsonb(config)::text,payload::text,dg_native_office_hash(payload),q.payload::jsonb->>'reason',1,meta->>'actorId',meta->>'sessionId',(meta->>'focusVersion')::bigint,p.access_version,created,created);
  INSERT INTO _dg_native_bill_operation_origins VALUES(operation_value,action_id_value,q.id,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),dg_native_office_hash(payload),created);
  PERFORM dg_native_dining_effect(action_id_value,'restaurant_financial_quotes',q.id);UPDATE restaurant_financial_quotes SET status='consumed' WHERE id=q.id;PERFORM dg_native_bill_refresh(action_id_value,b.id);PERFORM dg_native_bill_event(action_id_value,b.id,operation_value,'已明确确认并持久保存原请求；尚无可信收款或退款结果。');
 ELSE
  IF kind_value<>'operation' THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['version','action','confirmed']);SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target FOR UPDATE;
  IF body->>'action'<>'withdraw' OR body->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;IF operation.kind='refund' AND NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;
  IF dg_native_restaurant_integer(body->'version',1,9007199254740991)<>operation.version THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;IF operation.status<>'queued' OR operation.send_attempts<>0 OR operation.lease_token IS NOT NULL THEN PERFORM dg_native_bill_error('FINANCIAL_ALREADY_SENT');END IF;
  action_id_value:=dg_native_dining_action(meta,'bill_withdraw','party',p.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;bill_value:=b.id;PERFORM dg_native_dining_effect(action_id_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status='cancelled',version=version+1,updated_at=created WHERE id=operation.id;PERFORM dg_native_bill_refresh(action_id_value,b.id);PERFORM dg_native_bill_event(action_id_value,b.id,operation.id,'已撤回尚未发送的原请求；未生成收款、退款或远端关闭事实。');
 END IF;
 INSERT INTO _dg_native_bill_results VALUES(action_id_value,r.id,bill_value,p.access_version,created);RETURN action_id_value;
END;$dg$;

CREATE FUNCTION dg_native_bill_quote_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE q restaurant_financial_quotes%ROWTYPE;fixed _dg_native_bill_quote_origins%ROWTYPE;payload jsonb;reason_value text;
BEGIN
 SELECT * INTO q FROM restaurant_financial_quotes WHERE id=target;SELECT * INTO fixed FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;payload:=q.payload::jsonb;reason_value:=dg_native_bill_quote_reason(q.id,meta);
 RETURN jsonb_build_object('id',q.id,'billId',q.bill_id,'kind',q.kind,'parentPaymentId',q.parent_payment_id,'hash',q.hash,'billVersion',(payload->>'billVersion')::bigint,'orderContentVersion',(payload->>'orderContentVersion')::bigint,'amountMinor',(payload->>'amountMinor')::bigint,'currency','CNY','reason',payload->>'reason','lines',payload->'lines','valid',reason_value IS NULL,'invalidReason',reason_value,'confirmationToken',NULL,'expiresAt',q.expires_at,'createdAt',q.created_at,'_confirmation',CASE WHEN reason_value IS NULL THEN jsonb_build_object('quoteId',q.id,'meta',fixed.actor_meta,'hash',fixed.confirmation_hash) END);
END;$dg$;

CREATE FUNCTION dg_native_bill_operation_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;manager_value boolean;can_withdraw boolean;
BEGIN
 SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;manager_value:=dg_native_bill_manager(meta);can_withdraw:=operation.status='queued' AND operation.send_attempts=0 AND operation.lease_token IS NULL AND(operation.kind='payment' OR manager_value) AND(meta->>'actorType'='staff' OR dg_native_order_source(meta,meta->>'partyId'));
 RETURN jsonb_build_object('id',operation.id,'billId',operation.bill_id,'kind',operation.kind,'parentPaymentId',operation.parent_payment_id,'status',operation.status,'version',operation.version,'amountMinor',operation.amount_minor,'currency','CNY','reason',CASE WHEN operation.kind='refund' AND NOT manager_value THEN '门店经理核对退款' ELSE operation.reason END,'simulated',operation.simulated=1,'sendAttempts',operation.send_attempts,'simulateAttempts',operation.simulate_attempts,'lookups',operation.lookups,'nextAction',operation.next_action,'checkoutReady',false,'canSimulate',false,'canQuery',false,'canClose',false,'canWithdraw',can_withdraw,'refundableMinor',CASE WHEN operation.kind='payment' THEN coalesce(dg_native_bill_refundable(operation.id),0) ELSE 0 END,'remoteOperationId',operation.remote_operation_id,'remoteTransactionId',operation.remote_transaction_id,'errorMessage',operation.error_message,'createdAt',operation.created_at,'updatedAt',operation.updated_at);
END;$dg$;

CREATE FUNCTION dg_native_bill_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;t jsonb;reason_value text;connection jsonb;manager_value boolean;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;t:=dg_native_bill_totals(b.id);reason_value:=dg_native_bill_payment_reason(o.id,meta);connection:=dg_native_bill_connection(b.restaurant_id);manager_value:=dg_native_bill_manager(meta);
 IF reason_value IS NULL THEN
  IF(t->>'activePayments')::bigint>0 OR(t->>'activeRefunds')::bigint>0 THEN reason_value:='请先核对原资金请求，不能重复付款。';ELSIF(t->>'paid')::bigint>0 OR(t->>'balance')::bigint<=0 THEN reason_value:='此账单已无新的待收金额，请查看原收款及退款事实。';ELSIF b.attention_reason IS NOT NULL THEN reason_value:=b.attention_reason;ELSIF NOT(connection->>'configured')::boolean THEN reason_value:=connection->>'notice';END IF;
 END IF;
 RETURN jsonb_build_object('id',b.id,'restaurantId',b.restaurant_id,'partyId',b.party_id,'orderId',b.order_id,'orderVersion',o.version,'orderNumber',o.number,'number',b.number,'version',b.version,'orderContentVersion',b.order_content_version,'status',b.status,'totalMinor',b.amount_minor,'paidMinor',(t->>'paid')::bigint,'refundedMinor',(t->>'refunded')::bigint,'reservedRefundMinor',(t->>'reserved')::bigint,'balanceMinor',(t->>'balance')::bigint,'currency','CNY','attentionReason',b.attention_reason,'staleReason',CASE WHEN o.content_version<>b.order_content_version THEN '实际接单明细已变化，旧账单不能继续付款，请重新审阅。' END,'canReview',reason_value IS NULL,'reviewReason',reason_value,'canRefund',manager_value AND EXISTS(SELECT 1 FROM restaurant_financial_operations operation WHERE operation.bill_id=b.id AND operation.kind='payment' AND dg_native_bill_refundable(operation.id)>0),'settledAt',b.settled_at,'lines',b.snapshot::jsonb,
  'operations',(SELECT coalesce(jsonb_agg(dg_native_bill_operation_project(operation.id,meta) ORDER BY operation.created_at DESC,operation.id DESC),'[]') FROM restaurant_financial_operations operation JOIN _dg_native_bill_operation_origins fixed ON fixed.operation_id=operation.id WHERE operation.bill_id=b.id),
  'quotes',(SELECT coalesce(jsonb_agg(dg_native_bill_quote_project(quote.id,meta) ORDER BY quote.created_at DESC,quote.id DESC),'[]') FROM(SELECT q.id,q.created_at FROM restaurant_financial_quotes q JOIN _dg_native_bill_quote_origins fixed ON fixed.quote_id=q.id WHERE q.bill_id=b.id AND q.actor_id=meta->>'actorId' AND(q.kind='payment' OR manager_value) ORDER BY q.created_at DESC,q.id DESC LIMIT 10) quote),
  'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',event.id,'kind',event.kind,'message',event.info::jsonb->>'message','createdAt',event.created_at) ORDER BY event.created_at DESC,event.id DESC),'[]') FROM(SELECT * FROM restaurant_financial_events WHERE bill_id=b.id ORDER BY created_at DESC,id DESC LIMIT 50) event),'createdAt',b.created_at,'updatedAt',b.updated_at);
END;$dg$;

CREATE FUNCTION dg_native_bill_read(kind_value text,target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;connection jsonb;
BEGIN
 IF kind_value NOT IN('restaurant','party','bill') THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;meta:=dg_native_bill_context(kind_value,target,session_value,token_value);connection:=dg_native_bill_connection(meta->>'restaurantId',dg_native_bill_manager(meta));
 IF kind_value='restaurant' THEN RETURN connection;ELSIF kind_value='bill' THEN RETURN dg_native_bill_project(target,meta);END IF;
 RETURN jsonb_build_object('partyId',target,'bills',(SELECT coalesce(jsonb_agg(dg_native_bill_project(bill.id,meta) ORDER BY bill.created_at DESC,bill.id DESC),'[]') FROM(SELECT b.id,b.created_at FROM restaurant_bills b JOIN _dg_native_bill_origins fixed ON fixed.bill_id=b.id WHERE b.party_id=target ORDER BY b.created_at DESC,b.id DESC LIMIT 50) bill),'unbilledOrders',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',current_order.id,'number',current_order.number,'version',current_order.version,'contentVersion',current_order.content_version,'status',current_order.status,'totalMinor',coalesce((SELECT sum((line.quantity-line.cancelled_quantity)*line.unit_price_minor) FROM restaurant_order_lines line WHERE line.order_id=current_order.id),0)) ORDER BY current_order.created_at DESC,current_order.id DESC),'[]') FROM restaurant_orders current_order JOIN _dg_native_order_origins fixed ON fixed.order_id=current_order.id WHERE current_order.party_id=target AND NOT EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=current_order.id) AND EXISTS(SELECT 1 FROM restaurant_order_lines line WHERE line.order_id=current_order.id AND line.quantity>line.cancelled_quantity)),'connection',connection-ARRAY['canManage','scenario'],'automatic',meta->>'actorType'='staff' OR dg_native_order_source(meta,target),'canManage',dg_native_bill_manager(meta));
END;$dg$;

CREATE FUNCTION dg_native_bill_result(target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE result_value _dg_native_bill_results%ROWTYPE;actual_action _dg_native_dining_actions%ROWTYPE;meta jsonb;
BEGIN
 SELECT * INTO result_value FROM _dg_native_bill_results WHERE action_id=target;SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=target;IF result_value.action_id IS NULL THEN PERFORM dg_native_bill_error('NOT_FOUND');END IF;
 meta:=dg_native_bill_context(CASE WHEN actual_action.resource_type='restaurant' THEN 'restaurant' ELSE 'party' END,actual_action.resource_id,session_value,token_value);
 IF actual_action.actor_type IS DISTINCT FROM meta->>'actorType' OR actual_action.actor_id IS DISTINCT FROM meta->>'actorId' OR actual_action.actor_epoch IS DISTINCT FROM(meta->>'actorEpoch')::bigint OR actual_action.grant_version IS DISTINCT FROM(meta->>'grantVersion')::bigint OR actual_action.session_id IS DISTINCT FROM meta->>'sessionId' OR actual_action.access_id IS DISTINCT FROM meta->>'accessId' OR actual_action.focus_version IS DISTINCT FROM(meta->>'focusVersion')::bigint OR actual_action.selection_version IS DISTINCT FROM(meta->>'selectionVersion')::bigint OR result_value.party_access_version IS DISTINCT FROM(meta->>'partyAccessVersion')::bigint THEN PERFORM dg_native_bill_error('AUTHORIZATION_CHANGED');END IF;
 IF actual_action.kind='bill_config' THEN IF NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;RETURN dg_native_bill_connection(result_value.restaurant_id,true);END IF;RETURN dg_native_bill_project(result_value.bill_id,meta);
END;$dg$;

CREATE FUNCTION dg_native_bill_record_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);previous jsonb:=to_jsonb(OLD);record_value text;bill_value text;restaurant_value text;party_value text;actual_action _dg_native_dining_actions%ROWTYPE;
BEGIN
 record_value:=CASE WHEN TG_TABLE_NAME='restaurant_payment_configs' THEN j->>'restaurant_id' ELSE j->>'id' END;
 IF TG_OP='DELETE' OR NOT dg_native_dining_changed(TG_TABLE_NAME,record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native financial records require the exact durable scoped operation';END IF;
 IF TG_TABLE_NAME='restaurant_payment_configs' THEN restaurant_value:=j->>'restaurant_id';ELSE bill_value:=CASE WHEN TG_TABLE_NAME='restaurant_bills' THEN j->>'id' ELSE j->>'bill_id' END;SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_bills WHERE id=bill_value;IF TG_TABLE_NAME='restaurant_bills' THEN restaurant_value:=j->>'restaurant_id';party_value:=j->>'party_id';END IF;END IF;
 SELECT op.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions op ON op.id=effect.action_id WHERE effect.table_name=TG_TABLE_NAME AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND op.transaction_id=effect.transaction_id AND op.restaurant_id=restaurant_value AND op.resource_id=coalesce(party_value,restaurant_value) AND op.kind IN('bill_config','bill_review','bill_refund_review','bill_confirm','bill_withdraw') ORDER BY op.created_at DESC,op.id DESC LIMIT 1;
 IF actual_action.id IS NULL OR j->>'updated_at' IS NOT NULL AND j->>'updated_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial changes retain the original action, clock and store';END IF;
 IF TG_TABLE_NAME='restaurant_payment_configs' THEN
  IF actual_action.kind<>'bill_config' OR actual_action.actor_type<>'staff' OR j->>'merchant_id'<>'mock-merchant:'||restaurant_value OR j->>'provider_id' NOT IN('mock-payments','external-payments') OR(j->>'enabled')::bigint NOT IN(0,1) OR j->>'provider_id'='external-payments' AND(j->>'enabled')::bigint<>0 OR(j->>'version')::bigint<>(CASE WHEN TG_OP='INSERT' THEN 1 ELSE(previous->>'version')::bigint+1 END) OR TG_OP='UPDATE' AND j-ARRAY['provider_id','enabled','scenario','version','updated_at'] IS DISTINCT FROM previous-ARRAY['provider_id','enabled','scenario','version','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Payment configuration retains a derived merchant and explicit disabled real provider';END IF;
 ELSIF TG_TABLE_NAME='restaurant_bills' THEN
  IF TG_OP='INSERT' THEN IF actual_action.kind<>'bill_review' OR(j->>'version')::bigint<>1 OR j->>'created_at'<>actual_action.created_at OR j->>'status'<>'open' OR j->>'settled_at' IS NOT NULL OR j->>'attention_reason' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bills originate in a server review before any funds fact';END IF;
  ELSE
   IF(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['version','order_content_version','amount_minor','snapshot','status','attention_reason','settled_at','updated_at'] IS DISTINCT FROM previous-ARRAY['version','order_content_version','amount_minor','snapshot','status','attention_reason','settled_at','updated_at'] OR previous->>'settled_at' IS NOT NULL AND j->>'settled_at' IS DISTINCT FROM previous->>'settled_at' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bills preserve their original identity, settlement clock and monotone revision';END IF;
   IF j-ARRAY['version','status','attention_reason','settled_at','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','attention_reason','settled_at','updated_at'] AND(actual_action.kind<>'bill_review' OR EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE bill_id=bill_value) OR EXISTS(SELECT 1 FROM restaurant_financial_operations WHERE bill_id=bill_value AND status IN('queued','submitting','pending','unknown','needs_attention'))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial attempts or facts cannot be overwritten by a new price snapshot';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='restaurant_financial_quotes' THEN
  IF TG_OP='INSERT' THEN IF actual_action.kind NOT IN('bill_review','bill_refund_review') OR j->>'status'<>'current' OR j->>'created_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial quotes originate in an actual current review';END IF;
  ELSIF j-'status' IS DISTINCT FROM previous-'status' OR previous->>'status'<>'current' OR j->>'status' NOT IN('consumed','superseded') OR j->>'status'='consumed' AND actual_action.kind<>'bill_confirm' OR j->>'status'='superseded' AND actual_action.kind NOT IN('bill_review','bill_refund_review') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='The original quote payload, actor and expiry cannot be rewritten';END IF;
 ELSIF TG_TABLE_NAME='restaurant_financial_operations' THEN
  IF TG_OP='INSERT' THEN
   IF actual_action.kind<>'bill_confirm' OR j->>'status'<>'queued' OR(j->>'version')::bigint<>1 OR(j->>'send_attempts')::bigint<>0 OR(j->>'simulate_attempts')::bigint<>0 OR(j->>'lookups')::bigint<>0 OR(j->>'last_sequence')::bigint<>0 OR(j->>'simulated')::bigint<>1 OR j->>'created_at'<>actual_action.created_at OR j->>'lease_token' IS NOT NULL OR j->>'lease_until' IS NOT NULL OR j->>'lease_action' IS NOT NULL OR j->>'next_action' IS NOT NULL OR j->>'remote_operation_id' IS NOT NULL OR j->>'remote_transaction_id' IS NOT NULL OR j->>'error_code' IS NOT NULL OR j->>'error_message' IS NOT NULL OR j->>'last_lookup_at' IS NOT NULL OR j->>'action_actor_id' IS NOT NULL OR j->>'action_session_id' IS NOT NULL OR j->>'action_focus_version' IS NOT NULL OR j->>'action_party_access_version' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit confirmation creates only an unsent immutable financial request';END IF;
  ELSIF actual_action.kind<>'bill_withdraw' OR previous->>'status'<>'queued' OR(previous->>'send_attempts')::bigint<>0 OR previous->>'lease_token' IS NOT NULL OR j->>'status'<>'cancelled' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only an unsent request can be locally cancelled; no funds fact is fabricated';END IF;
 ELSIF TG_TABLE_NAME='restaurant_financial_events' THEN
  IF TG_OP<>'INSERT' OR j->>'actor_id'<>actual_action.actor_id OR j->>'kind'<>actual_action.kind OR j->>'created_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial events retain their original actor and clock';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Trusted financial transport and postings are not enabled by the review stage';END IF;RETURN NEW;
END;$dg$;

DO $bill_guards$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['restaurant_payment_configs','restaurant_bills','restaurant_financial_quotes','restaurant_financial_operations','restaurant_financial_events','restaurant_financial_receipts','restaurant_financial_postings','mock_financial_operations'] LOOP EXECUTE format('CREATE TRIGGER native_bill_record BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION dg_native_bill_record_guard()',table_value);END LOOP;END;$bill_guards$;

CREATE FUNCTION dg_native_bill_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE actual_action text;
BEGIN
 SELECT op.id INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions op ON op.id=effect.action_id WHERE effect.table_name='restaurant_bills' AND effect.resource_id=NEW.id AND effect.transaction_id=pg_current_xact_id()::text AND op.transaction_id=effect.transaction_id ORDER BY op.created_at DESC,op.id DESC LIMIT 1;
 INSERT INTO _dg_native_bill_revisions VALUES(NEW.id,NEW.version,actual_action,dg_native_office_hash(to_jsonb(NEW)),NEW.updated_at);RETURN NEW;
END;$dg$;
CREATE TRIGGER native_bill_revision AFTER INSERT OR UPDATE ON restaurant_bills FOR EACH ROW EXECUTE FUNCTION dg_native_bill_revision();

CREATE FUNCTION dg_native_bill_order_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE actual_action _dg_native_dining_actions%ROWTYPE;
BEGIN
 IF table_value<>'restaurant_orders' THEN RETURN false;END IF;SELECT op.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions op ON op.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=j->>'id' AND effect.transaction_id=pg_current_xact_id()::text AND op.transaction_id=effect.transaction_id AND op.restaurant_id=j->>'restaurant_id' AND op.resource_id=j->>'party_id' AND op.kind='bill_review' ORDER BY op.created_at DESC,op.id DESC LIMIT 1;IF actual_action.id IS NULL THEN RETURN false;END IF;
 IF operation_value<>'UPDATE' OR previous->>'settlement_status'<>'unsettled' OR j->>'settlement_status'<>'settled' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['settlement_status','status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['settlement_status','status','version','updated_at'] OR j->>'updated_at'<>actual_action.created_at OR NOT EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=j->>'id' AND bill.status='void' AND bill.amount_minor=0) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A zero bill can settle only its exact original empty order';END IF;RETURN true;
END;$dg$;

CREATE FUNCTION dg_native_bill_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;q restaurant_financial_quotes%ROWTYPE;operation restaurant_financial_operations%ROWTYPE;config restaurant_payment_configs%ROWTYPE;origin _dg_native_bill_origins%ROWTYPE;quote_origin _dg_native_bill_quote_origins%ROWTYPE;operation_origin _dg_native_bill_operation_origins%ROWTYPE;actual_action _dg_native_dining_actions%ROWTYPE;payload jsonb;state_value jsonb;bill_value text;meta jsonb;
BEGIN
 IF TG_TABLE_NAME='_dg_native_dining_actions' THEN
  SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=j->>'id';IF actual_action.kind NOT IN('bill_config','bill_review','bill_refund_review','bill_confirm','bill_withdraw') THEN RETURN NULL;END IF;
  IF NOT EXISTS(SELECT 1 FROM _dg_native_bill_results result_value WHERE result_value.action_id=actual_action.id AND result_value.restaurant_id=actual_action.restaurant_id AND result_value.created_at=actual_action.created_at AND(result_value.bill_id IS NULL AND actual_action.kind='bill_config' OR EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.id=result_value.bill_id AND bill.party_id=actual_action.resource_id))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial actions require their actual immutable result and original resource';END IF;RETURN NULL;
 END IF;
 IF TG_TABLE_NAME IN('restaurant_payment_configs','_dg_native_bill_config_revisions') THEN
  SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=j->>'restaurant_id';SELECT op.* INTO actual_action FROM _dg_native_bill_config_revisions revision JOIN _dg_native_dining_actions op ON op.id=revision.action_id WHERE revision.restaurant_id=config.restaurant_id AND revision.version=config.version AND revision.provider_id=config.provider_id AND revision.enabled=config.enabled AND revision.merchant_id=config.merchant_id AND revision.scenario=config.scenario AND revision.created_at=config.updated_at;
  meta:=jsonb_build_object('actorType',actual_action.actor_type,'actorId',actual_action.actor_id,'actorEpoch',actual_action.actor_epoch,'grantVersion',actual_action.grant_version,'restaurantId',config.restaurant_id);
  IF actual_action.id IS NULL OR actual_action.kind<>'bill_config' OR NOT dg_native_bill_manager(meta) OR actual_action.body_hash<>dg_native_office_hash(jsonb_build_object('version',config.version-1,'providerId',config.provider_id,'enabled',config.enabled=1,'scenario',config.scenario,'confirmed',true)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='The exact current manager and confirmed revision authorize payment configuration';END IF;RETURN NULL;
 END IF;
 bill_value:=CASE WHEN TG_TABLE_NAME='restaurant_bills' THEN j->>'id' WHEN TG_TABLE_NAME='_dg_native_bill_origins' OR TG_TABLE_NAME='_dg_native_bill_revisions' THEN j->>'bill_id' WHEN TG_TABLE_NAME='restaurant_financial_quotes' THEN j->>'bill_id' WHEN TG_TABLE_NAME='_dg_native_bill_quote_origins' THEN(SELECT bill_id FROM restaurant_financial_quotes WHERE id=j->>'quote_id') WHEN TG_TABLE_NAME='restaurant_financial_operations' THEN j->>'bill_id' WHEN TG_TABLE_NAME='_dg_native_bill_operation_origins' THEN(SELECT bill_id FROM restaurant_financial_operations WHERE id=j->>'operation_id') END;
 SELECT * INTO b FROM restaurant_bills WHERE id=bill_value;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;SELECT * INTO origin FROM _dg_native_bill_origins WHERE bill_id=b.id;state_value:=dg_native_bill_state(b.id);
 IF b.id IS NULL OR origin.bill_id IS NULL OR origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR origin.order_id<>o.id OR origin.party_id<>o.party_id OR b.party_id<>o.party_id OR b.restaurant_id<>o.restaurant_id OR origin.created_at<>b.created_at OR b.number<>'B-'||substring(o.number FROM 3) OR b.status<>state_value->>'status' OR b.attention_reason IS DISTINCT FROM state_value->>'attentionReason' OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_revisions revision JOIN _dg_native_dining_actions revision_action ON revision_action.id=revision.action_id WHERE revision.bill_id=b.id AND revision.version=b.version AND revision.row_hash=dg_native_office_hash(to_jsonb(b)) AND revision.created_at=b.updated_at AND revision_action.kind IN('bill_review','bill_confirm','bill_withdraw')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bills retain exact native order, derived totals, state and full row revision';END IF;
 IF b.amount_minor<>(SELECT coalesce(sum((line->>'subtotalMinor')::bigint),0) FROM jsonb_array_elements(b.snapshot::jsonb) line) OR EXISTS(SELECT 1 FROM jsonb_array_elements(b.snapshot::jsonb) line WHERE(line->>'subtotalMinor')::bigint<>(line->>'unitPriceMinor')::bigint*(line->>'quantity')::bigint) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Server bill totals equal the immutable original line arithmetic';END IF;
 IF EXISTS(SELECT 1 FROM _dg_native_bill_revisions revision JOIN _dg_native_dining_actions revision_action ON revision_action.id=revision.action_id WHERE revision.bill_id=b.id AND revision.version=b.version AND revision_action.kind='bill_review' AND revision_action.transaction_id=pg_current_xact_id()::text) AND(b.order_content_version<>o.content_version OR b.snapshot::jsonb IS DISTINCT FROM dg_native_bill_lines(o.id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A new review snapshots exactly the current accepted quantities and original prices';END IF;
 IF TG_TABLE_NAME IN('restaurant_financial_quotes','_dg_native_bill_quote_origins') THEN
  SELECT * INTO q FROM restaurant_financial_quotes WHERE id=CASE WHEN TG_TABLE_NAME='restaurant_financial_quotes' THEN j->>'id' ELSE j->>'quote_id' END;SELECT * INTO quote_origin FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=quote_origin.action_id;payload:=q.payload::jsonb;
  IF quote_origin.quote_id IS NULL OR quote_origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR quote_origin.payload_hash<>q.hash OR q.hash<>dg_native_office_hash(payload) OR q.id<>payload->>'id' OR q.bill_id<>b.id OR payload->>'billId'<>b.id OR payload->>'orderId'<>o.id OR payload->>'restaurantId'<>o.restaurant_id OR payload->>'partyId'<>o.party_id OR payload->>'expiresAt'<>q.expires_at OR q.created_at<>quote_origin.created_at OR q.expires_at<>quote_origin.expires_at OR q.expires_at<>dg_native_people_iso(q.created_at::timestamptz+interval '120 seconds') OR actual_action.created_at<>q.created_at OR actual_action.kind<>(CASE WHEN q.kind='payment' THEN 'bill_review' ELSE 'bill_refund_review' END) OR actual_action.actor_id IS DISTINCT FROM q.actor_id OR quote_origin.actor_meta->>'actorId' IS DISTINCT FROM q.actor_id OR quote_origin.actor_meta->>'sessionId' IS DISTINCT FROM q.session_id OR(quote_origin.actor_meta->>'focusVersion')::bigint IS DISTINCT FROM q.focus_version THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial quotes bind exact original actor, payload, fixed two minute deadline and runtime';END IF;
  IF actual_action.transaction_id=pg_current_xact_id()::text AND(q.expires_at<=dg_native_dining_now() OR q.kind='payment' AND NOT dg_native_order_source(quote_origin.actor_meta,o.party_id) OR q.kind='refund' AND NOT dg_native_bill_manager(quote_origin.actor_meta)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='New financial review must commit with its original actual authority';END IF;
 ELSIF TG_TABLE_NAME IN('restaurant_financial_operations','_dg_native_bill_operation_origins') THEN
  SELECT * INTO operation FROM restaurant_financial_operations WHERE id=CASE WHEN TG_TABLE_NAME='restaurant_financial_operations' THEN j->>'id' ELSE j->>'operation_id' END;SELECT * INTO operation_origin FROM _dg_native_bill_operation_origins WHERE operation_id=operation.id;SELECT * INTO q FROM restaurant_financial_quotes WHERE id=operation.quote_id;SELECT * INTO quote_origin FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=operation_origin.action_id;payload:=operation.request_payload::jsonb;
  IF operation_origin.operation_id IS NULL OR operation_origin.quote_id<>q.id OR q.status<>'consumed' OR operation_origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR operation_origin.request_hash<>operation.request_hash OR operation.request_hash<>dg_native_office_hash(payload) OR operation_origin.created_at<>operation.created_at OR actual_action.created_at<>operation.created_at OR actual_action.kind<>'bill_confirm' OR actual_action.body_hash<>dg_native_office_hash(jsonb_build_object('quoteId',q.id,'_confirmationHash',quote_origin.confirmation_hash,'confirmed',true)) OR operation.bill_id<>q.bill_id OR operation.kind<>q.kind OR operation.parent_payment_id IS DISTINCT FROM q.parent_payment_id OR operation.amount_minor<>(q.payload::jsonb->>'amountMinor')::bigint OR operation.actor_id IS DISTINCT FROM q.actor_id OR operation.session_id IS DISTINCT FROM q.session_id OR operation.focus_version IS DISTINCT FROM q.focus_version OR operation.party_access_version<>(quote_origin.actor_meta->>'partyAccessVersion')::bigint OR operation.provider_id<>'mock-payments' OR operation.merchant_id<>q.payload::jsonb->>'merchantId' OR operation.config_version<>(q.payload::jsonb->>'configVersion')::bigint OR(operation.config_snapshot::jsonb->>'version')::bigint<>operation.config_version OR operation.config_snapshot::jsonb->>'merchant_id'<>operation.merchant_id OR operation.config_snapshot::jsonb->>'provider_id'<>operation.provider_id OR payload IS DISTINCT FROM jsonb_build_object('operationId',operation.id,'kind',operation.kind,'restaurantId',b.restaurant_id,'billId',b.id,'orderId',b.order_id,'merchantId',operation.merchant_id,'amountMinor',operation.amount_minor,'currency','CNY','parentPaymentId',operation.parent_payment_id,'parentRemoteTransactionId',(SELECT remote_transaction_id FROM restaurant_financial_operations WHERE id=operation.parent_payment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial operations are exactly the explicitly confirmed immutable request and actor';END IF;
  IF actual_action.transaction_id=pg_current_xact_id()::text AND dg_native_bill_quote_reason(q.id,NULL,true) IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial confirmation retains actual quote, source, price and capacity until commit';END IF;
 END IF;RETURN NULL;
END;$dg$;
DO $bill_final$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['restaurant_payment_configs','_dg_native_bill_config_revisions','restaurant_bills','_dg_native_bill_origins','_dg_native_bill_revisions','restaurant_financial_quotes','_dg_native_bill_quote_origins','restaurant_financial_operations','_dg_native_bill_operation_origins','_dg_native_dining_actions'] LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER native_bill_final AFTER INSERT OR UPDATE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_bill_final()',table_value);END LOOP;END;$bill_final$;

CREATE OR REPLACE FUNCTION dg_native_order_record_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);previous jsonb:=to_jsonb(OLD);record_value text;restaurant_value text;party_value text;order_value text;action _dg_native_dining_actions%ROWTYPE;
BEGIN
 IF dg_native_bill_order_record(TG_TABLE_NAME,TG_OP,j,previous) THEN RETURN NEW;END IF;
 IF dg_native_order_kitchen_record(TG_TABLE_NAME,TG_OP,j,previous) THEN RETURN NEW;END IF;
 IF dg_native_order_transport_record(TG_TABLE_NAME,TG_OP,j,previous) THEN RETURN NEW;END IF;
 record_value:=CASE TG_TABLE_NAME WHEN 'restaurant_pos_configs' THEN j->>'restaurant_id' WHEN 'restaurant_order_dispatches' THEN j->>'change_id' ELSE j->>'id' END;
 IF TG_OP='DELETE' OR NOT dg_native_dining_changed(TG_TABLE_NAME,record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native order records require their actual scoped operation';END IF;
 IF TG_TABLE_NAME='restaurant_pos_configs' THEN restaurant_value:=j->>'restaurant_id';
 ELSIF TG_TABLE_NAME='restaurant_orders' THEN restaurant_value:=j->>'restaurant_id';party_value:=j->>'party_id';
 ELSE
  order_value:=CASE WHEN TG_TABLE_NAME='restaurant_order_changes' OR TG_TABLE_NAME='restaurant_order_events' OR TG_TABLE_NAME='restaurant_kitchen_tickets' THEN j->>'order_id' ELSE(SELECT c.order_id FROM restaurant_order_changes c WHERE c.id=j->>'change_id') END;
  SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_orders WHERE id=order_value;
 END IF;
 SELECT a.* INTO action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions a ON a.id=effect.action_id WHERE effect.table_name=TG_TABLE_NAME AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND a.transaction_id=effect.transaction_id AND a.restaurant_id=restaurant_value AND a.resource_id=coalesce(party_value,restaurant_value) AND a.kind IN('order_config','order_draft','order_update','order_review','order_confirm','order_submit','order_withdraw','order_expire','order_quote_expire') ORDER BY a.created_at DESC,a.id DESC LIMIT 1;
 IF action.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order effects cannot borrow unrelated business actions';END IF;
 IF TG_TABLE_NAME='restaurant_orders' THEN
  IF j->>'control_mode' NOT IN('automatic','human') OR j->>'settlement_status'<>'unsettled' OR(TG_OP='INSERT' AND(j->>'attention_reason' IS NOT NULL OR j->>'control_mode'<>'automatic')) OR(TG_OP='INSERT' AND(j->>'remote_order_id' IS NOT NULL OR(j->>'content_version')::bigint<>1)) OR j->>'status' NOT IN('draft','awaiting_confirmation','confirmed','queued','cancelled','accepted','preparing','ready','served','needs_attention') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='This order stage cannot fabricate acceptance, payment or remote facts';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_draft' OR j->>'status'<>'draft' OR(j->>'version')::bigint<>1 OR j->>'pending_change_id' IS NOT NULL OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native order creation is an unsubmitted original draft';END IF;
  ELSIF j-ARRAY['version','status','pending_change_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','pending_change_id','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR previous->>'status' IN('closed','cancelled') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order identity, accepted content and terminal states cannot be rewritten';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_changes' THEN
  IF j->>'source'<>'manual' OR j->>'source_request_id' IS NOT NULL OR j->>'kind' NOT IN('initial','amend','cancel') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Drafts cannot claim a fabricated conversation or source';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_draft' OR j->>'status'<>'draft' OR(j->>'version')::bigint<>1 OR j->>'created_at'<>action.created_at OR j->>'confirmed_at' IS NOT NULL OR j->>'current_quote_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order changes start as the next editable draft';END IF;
  ELSE
   IF j-ARRAY['version','status','input','base_content_version','actor_id','session_id','focus_version','party_access_version','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','input','base_content_version','actor_id','session_id','focus_version','party_access_version','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Change scope, sequence, source and version are immutable';END IF;
   IF NOT(action.kind='order_update' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed') AND j->>'status'='draft' OR action.kind='order_review' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed') AND j->>'status'='awaiting_confirmation' OR action.kind='order_confirm' AND previous->>'status'='awaiting_confirmation' AND j->>'status'='confirmed' OR action.kind='order_submit' AND previous->>'status'='confirmed' AND j->>'status'='queued' OR action.kind='order_withdraw' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed','queued','rejected','stale') AND j->>'status'='withdrawn' OR action.kind='order_expire' AND previous->>'status'='queued' AND j->>'status'='stale') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported order change transition';END IF;
   IF action.kind<>'order_update' AND j-ARRAY['version','status','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Review, confirmation and dispatch cannot rewrite draft input or attribution';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_quotes' THEN
  IF TG_OP='INSERT' THEN IF action.kind<>'order_review' OR j->>'status'<>'current' OR j->>'created_at'<>action.created_at OR(j->>'expires_at')::timestamptz<>(j->>'created_at')::timestamptz+interval '120 seconds' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quotes keep a fixed original two-minute deadline';END IF;
  ELSIF j-'status' IS DISTINCT FROM previous-'status' OR previous->>'status'<>'current' OR j->>'status' NOT IN('superseded','withdrawn','expired') OR j->>'status'='expired' AND j->>'expires_at'>dg_native_dining_now() THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quote content, attribution and original deadline cannot be replaced';END IF;
 ELSIF TG_TABLE_NAME='restaurant_pos_configs' THEN
  IF action.kind<>'order_config' OR j->>'provider_id' NOT IN('mock-pos','external-pos') OR(j->>'enabled')::bigint NOT IN(0,1) OR j->>'provider_id'='external-pos' AND j->>'enabled'<>'0' OR j->>'scenario' NOT IN('normal','rejected','response_lost','unresolved') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native POS configuration cannot silently simulate a live provider';END IF;
  IF TG_OP='INSERT' THEN IF(j->>'version')::bigint<>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='POS config starts at version one';END IF;
  ELSIF j-ARRAY['provider_id','enabled','scenario','version','updated_at'] IS DISTINCT FROM previous-ARRAY['provider_id','enabled','scenario','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='POS config versions and original creation are guarded';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_dispatches' THEN
  IF TG_OP='INSERT' THEN IF action.kind<>'order_submit' OR j->>'status'<>'queued' OR j->>'attempts'<>'0' OR j->>'version'<>'1' OR j->>'simulated'<>'1' OR j->>'provider_id'<>'mock-pos' OR j->>'lease_token' IS NOT NULL OR j->>'lease_until' IS NOT NULL OR j->>'remote_request_id' IS NOT NULL OR j->>'remote_order_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A persistent dispatch is queued and has not claimed external success';END IF;
  ELSIF action.kind NOT IN('order_withdraw','order_expire') OR previous->>'status'<>'queued' OR previous->>'attempts'<>'0' OR j->>'status'<>'cancelled' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['status','version','error_code','error_message','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','error_code','error_message','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only definitely unsent dispatches can be withdrawn in this stage';END IF;
 ELSIF TG_TABLE_NAME='restaurant_inventory_reservations' THEN
  IF(j->>'quantity')::bigint<=0 OR j->>'tracked' NOT IN('0','1') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Inventory reservation quantities are positive and explicitly tracked';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_submit' OR j->>'status'<>'reserved' OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reservations originate in the atomic submit';END IF;
  ELSIF action.kind NOT IN('order_withdraw','order_expire') OR previous->>'status'<>'reserved' OR j->>'status'<>'released' OR j-ARRAY['status','updated_at'] IS DISTINCT FROM previous-ARRAY['status','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only original reservations can be released once';END IF;
 ELSIF TG_TABLE_NAME='restaurant_stock_movements' THEN
  IF TG_OP<>'INSERT' OR j->>'kind' NOT IN('reserve','release') OR(j->>'before_quantity')::bigint<0 OR(j->>'after_quantity')::bigint<0 OR NOT(action.kind='order_submit' AND j->>'kind'='reserve' AND(j->>'before_quantity')::bigint>(j->>'after_quantity')::bigint OR action.kind IN('order_withdraw','order_expire') AND j->>'kind'='release' AND(j->>'before_quantity')::bigint<(j->>'after_quantity')::bigint) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stock movements are append-only actual reservation or release deltas';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_events' THEN
  IF TG_OP<>'INSERT' OR j->>'actor_id'<>action.actor_id OR j->>'kind'<>action.kind OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order events retain their actual operation and actor';END IF;
 ELSE
  IF TG_TABLE_NAME<>'restaurant_kitchen_tickets' OR TG_OP<>'UPDATE' OR action.kind NOT IN('order_submit','order_withdraw','order_expire') OR j-ARRAY['pending_cancel_quantity','version','updated_at'] IS DISTINCT FROM previous-ARRAY['pending_cancel_quantity','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'pending_cancel_quantity')::bigint<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='This stage cannot fabricate kitchen progress';END IF;
 END IF;RETURN NEW;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_dining_business_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);party_value text;p dining_parties%ROWTYPE;r restaurants%ROWTYPE;origin _dg_native_dining_party_origins%ROWTYPE;b dining_reservations%ROWTYPE;o dining_occupancies%ROWTYPE;t restaurant_tables%ROWTYPE;plan dining_hold_plans%ROWTYPE;a _dg_native_dining_actions%ROWTYPE;s reception_sessions%ROWTYPE;booking_clock _dg_native_dining_booking_clocks%ROWTYPE;latest record;
BEGIN
 IF TG_TABLE_NAME='_dg_native_dining_actions' THEN
  SELECT * INTO a FROM _dg_native_dining_actions WHERE id=j->>'id';SELECT * INTO r FROM restaurants WHERE id=a.restaurant_id;
  IF a.actor_type='staff' AND NOT(CASE WHEN a.kind IN('kitchen_start','kitchen_ready','kitchen_serve') THEN dg_native_order_kitchen_authority(a.actor_id,a.restaurant_id,a.actor_epoch,a.grant_version,CASE WHEN a.kind='kitchen_serve' THEN 'serve' ELSE 'cook' END) ELSE dg_native_dining_clock_authority(a.actor_id,a.restaurant_id,a.actor_epoch,a.grant_version) END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining staff operation must commit with its original current authority';END IF;
  IF a.resource_type='restaurant' AND a.kind='bill_config' THEN
   IF a.actor_type<>'staff' OR a.resource_id IS DISTINCT FROM r.id OR r.environment<>'mock' OR r.app_env IS DISTINCT FROM(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_config_revisions revision WHERE revision.action_id=a.id AND revision.restaurant_id=r.id AND revision.created_at=a.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Store payment configuration requires its original immutable revision';END IF;RETURN NULL;
  END IF;
  IF a.resource_type='restaurant' THEN
   IF a.kind<>'order_config' OR a.actor_type<>'staff' OR a.resource_id IS DISTINCT FROM r.id OR r.environment<>'mock' OR r.app_env IS DISTINCT FROM(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR NOT EXISTS(SELECT 1 FROM _dg_native_order_pos_revisions fixed WHERE fixed.action_id=a.id AND fixed.restaurant_id=r.id AND fixed.created_at=a.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Store configuration action requires its exact immutable POS revision';END IF;RETURN NULL;
  END IF;
  IF a.actor_type='guest' THEN SELECT * INTO s FROM reception_sessions WHERE id=a.session_id;IF s.status<>'active' OR s.expires_at<=dg_native_dining_now() OR NOT dg_native_reception_source_valid(s.id) OR s.focus_version<>a.focus_version OR NOT EXISTS(SELECT 1 FROM _dg_native_reception_access WHERE id=a.access_id AND session_id=s.id AND access_version=s.access_version) OR coalesce((SELECT max(version) FROM _dg_native_dining_selection_revisions WHERE session_id=s.id),0)<>a.selection_version THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining guest operation keeps its actual session, access, person and selection';END IF;END IF;
  IF a.resource_type='plan' THEN SELECT party_id INTO party_value FROM dining_hold_plans WHERE id=a.resource_id;ELSE party_value:=a.resource_id;END IF;
 ELSIF TG_TABLE_NAME='_dg_native_dining_selection_revisions' THEN
  SELECT * INTO s FROM reception_sessions WHERE id=j->>'session_id';SELECT * INTO a FROM _dg_native_dining_actions WHERE id=j->>'action_id';SELECT version,party_id INTO latest FROM _dg_native_dining_selection_revisions WHERE session_id=s.id ORDER BY version DESC LIMIT 1;
  IF s.service_scene<>'restaurant' OR latest.party_id IS DISTINCT FROM s.dining_party_id OR (j->>'version')::bigint<>coalesce((SELECT max(version) FROM _dg_native_dining_selection_revisions WHERE session_id=s.id AND version<(j->>'version')::bigint),0)+1 OR a.transaction_id<>pg_current_xact_id()::text OR a.kind NOT IN('create','reserve','select','claim') OR NOT dg_native_dining_changed('reception_sessions',s.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining selection revisions preserve their original monotonic target';END IF;RETURN NULL;
 ELSIF TG_TABLE_NAME='dining_parties' THEN party_value:=j->>'id';
 ELSIF TG_TABLE_NAME='_dg_native_dining_party_origins' THEN party_value:=j->>'party_id';
 ELSIF TG_TABLE_NAME IN('dining_reservations','dining_occupancies','dining_hold_plans') THEN party_value:=j->>'party_id';
 ELSIF TG_TABLE_NAME='_dg_native_dining_plan_origins' THEN SELECT * INTO plan FROM dining_hold_plans WHERE id=j->>'plan_id';party_value:=plan.party_id;
 ELSIF TG_TABLE_NAME='_dg_native_dining_occupancy_origins' THEN SELECT * INTO o FROM dining_occupancies WHERE id=j->>'occupancy_id';party_value:=o.party_id;
 ELSIF TG_TABLE_NAME='_dg_native_dining_booking_clocks' THEN
  SELECT * INTO b FROM dining_reservations WHERE id=j->>'reservation_id';SELECT * INTO a FROM _dg_native_dining_actions WHERE id=j->>'action_id';party_value:=b.party_id;
  IF a.transaction_id<>pg_current_xact_id()::text OR a.kind NOT IN('reserve','reschedule') OR a.resource_id<>party_value OR(j->>'revision')::bigint<>b.version OR j->>'starts_at' IS DISTINCT FROM b.starts_at OR j->>'ends_at' IS DISTINCT FROM b.ends_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Booking clock revisions require the actual confirmed time operation';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported dining invariant source';END IF;
 SELECT * INTO p FROM dining_parties WHERE id=party_value;SELECT * INTO origin FROM _dg_native_dining_party_origins WHERE party_id=p.id;SELECT * INTO r FROM restaurants WHERE id=p.restaurant_id;
 IF p.id IS NULL OR origin.party_id IS NULL OR origin.restaurant_id<>p.restaurant_id OR origin.runtime_id IS DISTINCT FROM(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR origin.tenant_id<>r.tenant_id OR origin.workspace_id<>r.workspace_id OR origin.created_at<>p.created_at OR p.owner_session_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM _dg_native_dining_session_origins WHERE session_id=p.owner_session_id AND restaurant_id=r.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining facts retain native runtime, store and consent ownership';END IF;
 SELECT * INTO b FROM dining_reservations WHERE party_id=p.id;SELECT * INTO o FROM dining_occupancies WHERE party_id=p.id AND state IN('held','seated');
 IF p.status='reserved' AND(b.id IS NULL OR b.status<>'confirmed') OR p.status='held' AND(o.id IS NULL OR o.state<>'held') OR p.status='seated' AND(o.id IS NULL OR o.state<>'seated') OR p.status NOT IN('held','seated') AND o.id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining party state and actual occupancy must agree';END IF;
 IF b.id IS NOT NULL THEN
  booking_clock:=dg_native_dining_booking_clock(b.id);IF booking_clock.reservation_id IS NULL OR booking_clock.starts_at<>b.starts_at OR booking_clock.ends_at<>b.ends_at OR booking_clock.checkin_opens_at<>dg_native_people_iso(b.starts_at::timestamptz-interval '30 minutes') OR booking_clock.late_deadline<b.starts_at OR booking_clock.late_deadline>dg_native_people_iso(b.starts_at::timestamptz+interval '60 minutes') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reservation clocks retain their original confirmed time revision';END IF;
  SELECT * INTO t FROM restaurant_tables WHERE id=b.table_id;IF b.restaurant_id<>r.id OR t.restaurant_id<>r.id OR b.status IN('confirmed','checked_in') AND NOT dg_native_dining_fits(t,p.size) OR EXISTS(SELECT 1 FROM dining_reservations other WHERE other.restaurant_id=r.id AND other.id<>b.id AND other.table_id=b.table_id AND other.status IN('confirmed','checked_in') AND b.status IN('confirmed','checked_in') AND other.starts_at<b.ends_at AND other.ends_at>b.starts_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining reservations cannot overlap or lose their scoped table capacity';END IF;
 END IF;
 IF o.id IS NOT NULL THEN
  SELECT * INTO t FROM restaurant_tables WHERE id=o.table_id;IF o.restaurant_id<>r.id OR t.restaurant_id<>r.id OR NOT dg_native_dining_fits(t,p.size) OR t.operation<>'open' OR NOT EXISTS(SELECT 1 FROM _dg_native_dining_occupancy_origins WHERE occupancy_id=o.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Active dining occupancy requires its actual scoped, enabled table and immutable plan';END IF;
 END IF;
 IF TG_TABLE_NAME IN('dining_hold_plans','_dg_native_dining_plan_origins') THEN
  SELECT * INTO plan FROM dining_hold_plans WHERE id=CASE WHEN TG_TABLE_NAME='dining_hold_plans' THEN j->>'id' ELSE j->>'plan_id' END;SELECT action.* INTO a FROM _dg_native_dining_plan_origins binding JOIN _dg_native_dining_actions action ON action.id=binding.action_id WHERE binding.plan_id=plan.id;
  IF plan.id IS NULL OR a.id IS NULL OR a.kind<>'plan' OR a.resource_id<>plan.id OR a.restaurant_id<>plan.restaurant_id OR a.actor_id<>plan.actor_id OR a.focus_version IS DISTINCT FROM plan.focus_version OR NOT EXISTS(SELECT 1 FROM restaurant_tables WHERE id=plan.table_id AND restaurant_id=plan.restaurant_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining plans keep the actual immutable action and table source';END IF;
 END IF;RETURN NULL;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_dining_apply(kind_value text,target text,action_value text,input jsonb,session_value text DEFAULT NULL,token_hash_value text DEFAULT NULL,csrf_hash_value text DEFAULT NULL,focus_value bigint DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;body jsonb:=input-ARRAY['confirmed','focusVersion','selectionVersion'];r restaurants%ROWTYPE;p dining_parties%ROWTYPE;b dining_reservations%ROWTYPE;o dining_occupancies%ROWTYPE;t restaurant_tables%ROWTYPE;plan dining_hold_plans%ROWTYPE;booking_clock _dg_native_dining_booking_clocks%ROWTYPE;dining_action_identifier text;resource_value text;party_value text;table_value text;previous_table text;now_value text:=dg_native_dining_now();start_value text;end_value text;counter_value bigint;version_value bigint;party_version bigint;projection jsonb;old_owner reception_sessions%ROWTYPE;
BEGIN
 IF action_value NOT IN('create','reserve','update','reschedule','check_in','plan','hold','seat','release','cancel','finish','select','claim') THEN PERFORM dg_native_dining_error('VALIDATION_FAILED');END IF;
 IF jsonb_typeof(input)<>'object' OR action_value<>'plan' AND input->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_dining_error('VALIDATION_FAILED');END IF;
 meta:=dg_native_dining_context(kind_value,target,session_value,token_hash_value,csrf_hash_value,focus_value,true);SELECT * INTO r FROM restaurants WHERE id=meta->>'restaurantId';now_value:=dg_native_dining_now();
 IF session_value IS NOT NULL AND dg_native_restaurant_integer(input->'selectionVersion',0,9007199254740991)<>(meta->>'selectionVersion')::bigint THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;
 IF meta->>'partyId' IS NOT NULL THEN p:=dg_native_dining_owned(meta,meta->>'partyId');END IF;
 IF session_value IS NOT NULL AND p.id IS NOT NULL AND action_value<>'select' AND NOT EXISTS(SELECT 1 FROM reception_sessions WHERE id=session_value AND dining_party_id=p.id) THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;
 IF action_value IN('create','reserve') THEN party_value:=body->'_ticket'->>'partyId';resource_value:=party_value;
 ELSIF action_value='plan' THEN resource_value:=gen_random_uuid()::text;party_value:=p.id;
 ELSIF action_value='claim' THEN party_value:=body->>'partyId';resource_value:=party_value;
 ELSE party_value:=p.id;resource_value:=party_value;END IF;
 IF resource_value IS NULL THEN PERFORM dg_native_dining_error('VALIDATION_FAILED');END IF;
 dining_action_identifier:=dg_native_dining_action(meta,action_value,CASE WHEN action_value='plan' THEN 'plan' ELSE 'party' END,resource_value,body);
 IF action_value IN('update','cancel','finish','select','plan','reschedule','check_in','seat','release') THEN version_value:=dg_native_restaurant_integer(body->'version',1,9007199254740991);END IF;
 CASE action_value
 WHEN 'create' THEN
  IF kind_value<>'restaurant' THEN PERFORM dg_native_dining_error('VALIDATION_FAILED');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['name','size','visitMinutes','guestNote','_ticket']);PERFORM dg_native_dining_new_party(meta,dining_action_identifier,body-'_ticket',body->'_ticket');PERFORM dg_native_dining_touch(meta,dining_action_identifier,party_value,true);
 WHEN 'reserve' THEN
  IF kind_value<>'restaurant' THEN PERFORM dg_native_dining_error('VALIDATION_FAILED');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['party','tableId','startsAt','endsAt','_ticket']);table_value:=dg_native_dining_booking_table(r,body);start_value:=dg_native_dining_iso(body->>'startsAt');end_value:=dg_native_dining_iso(body->>'endsAt');PERFORM dg_native_dining_new_party(meta,dining_action_identifier,body->'party',body->'_ticket',true,dg_native_people_iso(end_value::timestamptz+interval '24 hours'));
  PERFORM dg_native_dining_effect(dining_action_identifier,'restaurants',r.id);UPDATE restaurants SET booking_counter=booking_counter+1,updated_at=now_value WHERE id=r.id RETURNING booking_counter INTO counter_value;
  b.id:=gen_random_uuid()::text;PERFORM dg_native_dining_effect(dining_action_identifier,'dining_reservations',b.id);INSERT INTO dining_reservations(id,restaurant_id,party_id,table_id,reference,starts_at,ends_at,created_at) VALUES(b.id,r.id,party_value,table_value,'R-'||CASE WHEN length(counter_value::text)<6 THEN lpad(counter_value::text,6,'0') ELSE counter_value::text END,start_value,end_value,now_value);INSERT INTO _dg_native_dining_booking_clocks VALUES(b.id,1,start_value,end_value,dg_native_people_iso(start_value::timestamptz-interval '30 minutes'),dg_native_people_iso(start_value::timestamptz+make_interval(mins=>r.late_minutes::integer)),dining_action_identifier,now_value);PERFORM dg_native_dining_table_touch(dining_action_identifier,table_value);PERFORM dg_native_dining_touch(meta,dining_action_identifier,party_value,true);
 WHEN 'update' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['name','size','visitMinutes','guestNote','version']);PERFORM dg_native_dining_fields(body-'version');IF p.version<>version_value THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;IF p.status NOT IN('waiting','reserved') THEN PERFORM dg_native_dining_error('PARTY_ALREADY_ASSIGNED');END IF;
  SELECT * INTO b FROM dining_reservations WHERE party_id=p.id AND status IN('confirmed','checked_in');IF b.id IS NOT NULL THEN SELECT * INTO t FROM restaurant_tables WHERE id=b.table_id;IF NOT dg_native_dining_fits(t,(body->>'size')::bigint) THEN PERFORM dg_native_dining_error('BOOKING_CAPACITY');END IF;END IF;
  PERFORM dg_native_dining_effect(dining_action_identifier,'dining_parties',p.id);UPDATE dining_parties SET name=btrim(body->>'name'),size=(body->>'size')::bigint,visit_minutes=(body->>'visitMinutes')::bigint,guest_note=body->>'guestNote',version=version+1,updated_at=now_value WHERE id=p.id;PERFORM dg_native_dining_touch(meta,dining_action_identifier);
 WHEN 'reschedule' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['party','tableId','startsAt','endsAt','version','partyVersion','_ticket']);SELECT * INTO b FROM dining_reservations WHERE id=target;party_version:=dg_native_restaurant_integer(body->'partyVersion',1,9007199254740991);
  IF b.version<>version_value OR p.version<>party_version THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;IF b.status<>'confirmed' OR p.status<>'reserved' THEN PERFORM dg_native_dining_error('BOOKING_LOCKED');END IF;previous_table:=b.table_id;table_value:=dg_native_dining_booking_table(r,body,p.id);start_value:=dg_native_dining_iso(body->>'startsAt');end_value:=dg_native_dining_iso(body->>'endsAt');
  PERFORM dg_native_dining_ticket_fields(body->'_ticket',p.id);PERFORM dg_native_dining_effect(dining_action_identifier,'dining_reservations',b.id);UPDATE dining_reservations SET table_id=table_value,starts_at=start_value,ends_at=end_value,version=version+1 WHERE id=b.id;PERFORM dg_native_dining_effect(dining_action_identifier,'dining_parties',p.id);UPDATE dining_parties SET name=btrim(body->'party'->>'name'),size=(body->'party'->>'size')::bigint,visit_minutes=(body->'party'->>'visitMinutes')::bigint,guest_note=body->'party'->>'guestNote',claim_nonce=body->'_ticket'->>'nonce',claim_hash=body->'_ticket'->>'sha256',claim_expires_at=dg_native_people_iso(end_value::timestamptz+interval '24 hours'),access_version=access_version+1,version=version+1,updated_at=now_value WHERE id=p.id;
  INSERT INTO _dg_native_dining_booking_clocks VALUES(b.id,b.version+1,start_value,end_value,dg_native_people_iso(start_value::timestamptz-interval '30 minutes'),dg_native_people_iso(start_value::timestamptz+make_interval(mins=>r.late_minutes::integer)),dining_action_identifier,now_value);PERFORM dg_native_dining_table_touch(dining_action_identifier,previous_table);IF previous_table<>table_value THEN PERFORM dg_native_dining_table_touch(dining_action_identifier,table_value);END IF;PERFORM dg_native_dining_touch(meta,dining_action_identifier);
 WHEN 'check_in' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['version']);SELECT * INTO b FROM dining_reservations WHERE id=target;IF b.version<>version_value THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;
  booking_clock:=dg_native_dining_booking_clock(b.id);IF b.status<>'confirmed' OR p.status<>'reserved' OR booking_clock.reservation_id IS NULL OR now_value<booking_clock.checkin_opens_at OR now_value>booking_clock.late_deadline THEN PERFORM dg_native_dining_error('CHECK_IN_WINDOW');END IF;
  PERFORM dg_native_dining_effect(dining_action_identifier,'dining_reservations',b.id);UPDATE dining_reservations SET status='checked_in',version=version+1 WHERE id=b.id;counter_value:=dg_native_dining_queue(r,dining_action_identifier);PERFORM dg_native_dining_effect(dining_action_identifier,'dining_parties',p.id);UPDATE dining_parties SET status='waiting',queue_number=counter_value,queued_at=now_value,version=version+1,updated_at=now_value WHERE id=p.id;PERFORM dg_native_dining_table_touch(dining_action_identifier,b.table_id);PERFORM dg_native_dining_touch(meta,dining_action_identifier);
 WHEN 'plan' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['partyId','version','tableId']);IF body->>'partyId' IS DISTINCT FROM p.id OR p.version<>version_value THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;PERFORM dg_native_dining_plan(meta,p,body->>'tableId',dining_action_identifier,resource_value);PERFORM dg_native_dining_touch(meta,dining_action_identifier);
 WHEN 'hold' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['planId','planHash']);SELECT * INTO plan FROM dining_hold_plans WHERE id=target;IF body->>'planId' IS DISTINCT FROM plan.id OR body->>'planHash' IS DISTINCT FROM plan.hash THEN PERFORM dg_native_dining_error('TABLE_PLAN_CHANGED');END IF;projection:=dg_native_dining_plan_projection(plan.id,meta);IF projection->'valid' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_dining_error('TABLE_PLAN_CHANGED');END IF;PERFORM dg_native_dining_assert_open(r,now_value,plan.expected_end_at);
  o.id:=gen_random_uuid()::text;PERFORM dg_native_dining_effect(dining_action_identifier,'dining_occupancies',o.id);INSERT INTO dining_occupancies(id,restaurant_id,table_id,party_id,state,expires_at,expected_end_at,actor_id,created_at,updated_at) VALUES(o.id,r.id,plan.table_id,p.id,'held',least(dg_native_people_iso(now_value::timestamptz+make_interval(secs=>r.hold_seconds::double precision)),plan.expected_end_at),plan.expected_end_at,meta->>'actorId',now_value,now_value);INSERT INTO _dg_native_dining_occupancy_origins VALUES(o.id,plan.id,dining_action_identifier);PERFORM dg_native_dining_effect(dining_action_identifier,'dining_parties',p.id);UPDATE dining_parties SET status='held',version=version+1,updated_at=now_value WHERE id=p.id;PERFORM dg_native_dining_table_touch(dining_action_identifier,plan.table_id);PERFORM dg_native_dining_touch(meta,dining_action_identifier);
 WHEN 'seat','release' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['version','partyVersion','_ticket']);SELECT * INTO o FROM dining_occupancies WHERE id=target;party_version:=dg_native_restaurant_integer(body->'partyVersion',1,9007199254740991);IF o.version<>version_value OR p.version<>party_version THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;
  IF o.state<>'held' OR o.expires_at IS NULL OR o.expires_at<=now_value OR p.status<>'held' THEN PERFORM dg_native_dining_error('HOLD_EXPIRED');END IF;SELECT * INTO t FROM restaurant_tables WHERE id=o.table_id;
  PERFORM dg_native_dining_effect(dining_action_identifier,'dining_occupancies',o.id);PERFORM dg_native_dining_effect(dining_action_identifier,'dining_parties',p.id);
  IF action_value='release' THEN UPDATE dining_occupancies SET state='released',version=version+1,updated_at=now_value WHERE id=o.id;UPDATE dining_parties SET status='waiting',version=version+1,updated_at=now_value WHERE id=p.id;
  ELSE
   IF t.operation<>'open' OR NOT dg_native_dining_fits(t,p.size) OR dg_native_dining_conflict(r.id,t.id,now_value,o.expected_end_at,p.id) THEN PERFORM dg_native_dining_error('TABLE_CHANGED');END IF;PERFORM dg_native_dining_assert_open(r,now_value,o.expected_end_at);PERFORM dg_native_dining_ticket_fields(body->'_ticket',p.id);
   UPDATE dining_occupancies SET state='seated',expires_at=NULL,version=version+1,updated_at=now_value WHERE id=o.id;UPDATE dining_parties SET status='seated',seated_at=now_value,version=version+1,access_version=access_version+1,claim_nonce=body->'_ticket'->>'nonce',claim_hash=body->'_ticket'->>'sha256',updated_at=now_value WHERE id=p.id;
   SELECT * INTO b FROM dining_reservations WHERE party_id=p.id AND status='checked_in';IF b.id IS NOT NULL THEN PERFORM dg_native_dining_effect(dining_action_identifier,'dining_reservations',b.id);UPDATE dining_reservations SET status='seated',version=version+1 WHERE id=b.id;END IF;
  END IF;PERFORM dg_native_dining_table_touch(dining_action_identifier,t.id);PERFORM dg_native_dining_touch(meta,dining_action_identifier);
 WHEN 'cancel','finish' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['version']);IF p.version<>version_value THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;
  IF p.status NOT IN('waiting','reserved','held','seated') THEN PERFORM dg_native_dining_error('PARTY_ENDED');END IF;
  IF action_value='cancel' AND p.status='seated' THEN PERFORM dg_native_dining_error('PARTY_SEATED');END IF;
  IF action_value='finish' AND(meta->>'actorType'<>'staff' OR p.status<>'seated') THEN PERFORM dg_native_dining_error('FORBIDDEN');END IF;
  IF NOT dg_native_bill_party_finishable(p.id) THEN PERFORM dg_native_dining_error('FINANCIAL_PENDING');END IF;
  SELECT * INTO o FROM dining_occupancies WHERE party_id=p.id AND state IN('held','seated');IF o.id IS NOT NULL THEN PERFORM dg_native_dining_effect(dining_action_identifier,'dining_occupancies',o.id);UPDATE dining_occupancies SET state='released',version=version+1,updated_at=now_value WHERE id=o.id;PERFORM dg_native_dining_table_touch(dining_action_identifier,o.table_id,action_value='finish');END IF;
  SELECT * INTO b FROM dining_reservations WHERE party_id=p.id AND status IN('confirmed','checked_in','seated');IF b.id IS NOT NULL THEN PERFORM dg_native_dining_effect(dining_action_identifier,'dining_reservations',b.id);UPDATE dining_reservations SET status=CASE WHEN action_value='finish' THEN 'completed' ELSE 'cancelled' END,version=version+1 WHERE id=b.id;IF o.id IS NULL OR o.table_id<>b.table_id THEN PERFORM dg_native_dining_table_touch(dining_action_identifier,b.table_id);END IF;END IF;
  PERFORM dg_native_dining_effect(dining_action_identifier,'dining_parties',p.id);UPDATE dining_parties SET status=CASE WHEN action_value='finish' THEN 'completed' ELSE 'cancelled' END,version=version+1,access_version=access_version+1,ended_at=now_value,updated_at=now_value WHERE id=p.id;PERFORM dg_native_dining_touch(meta,dining_action_identifier);
 WHEN 'select' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['version']);IF meta->>'actorType'<>'guest' THEN PERFORM dg_native_dining_error('FORBIDDEN');END IF;IF p.version<>version_value THEN PERFORM dg_native_dining_error('VERSION_CONFLICT');END IF;IF p.status NOT IN('waiting','reserved','held','seated') THEN PERFORM dg_native_dining_error('PARTY_ENDED');END IF;PERFORM dg_native_dining_touch(meta,dining_action_identifier,p.id,true);
 WHEN 'claim' THEN
  PERFORM dg_native_restaurant_fields(body,ARRAY['partyId','version','codeHash','_ticket']);IF meta->>'actorType'<>'guest' THEN PERFORM dg_native_dining_error('FORBIDDEN');END IF;SELECT * INTO p FROM dining_parties WHERE id=body->>'partyId' FOR UPDATE;
  IF p.id IS NULL OR p.restaurant_id<>r.id OR NOT EXISTS(SELECT 1 FROM _dg_native_dining_party_origins WHERE party_id=p.id) OR p.status NOT IN('waiting','reserved','held','seated') OR p.claim_expires_at<=now_value OR p.claim_hash IS DISTINCT FROM body->>'codeHash' OR p.version::text IS DISTINCT FROM body->>'version' THEN PERFORM dg_native_dining_error('INVALID_DINING_CLAIM');END IF;
  IF p.owner_session_id IS DISTINCT FROM session_value AND(SELECT count(*) FROM dining_parties WHERE owner_session_id=session_value AND restaurant_id=r.id AND status IN('waiting','reserved','held','seated'))>=5 THEN PERFORM dg_native_dining_error('PARTY_LIMIT');END IF;PERFORM dg_native_dining_ticket_fields(body->'_ticket',p.id);
  SELECT * INTO old_owner FROM reception_sessions WHERE id=p.owner_session_id;IF old_owner.id IS NOT NULL AND old_owner.id<>session_value AND old_owner.status IN('active','human') AND old_owner.dining_party_id=p.id THEN PERFORM dg_native_dining_effect(dining_action_identifier,'reception_sessions',old_owner.id);PERFORM dg_native_reception_cancel(old_owner.id);INSERT INTO _dg_native_dining_selection_revisions SELECT old_owner.id,coalesce(max(version),0)+1,NULL,dining_action_identifier,now_value FROM _dg_native_dining_selection_revisions WHERE session_id=old_owner.id;UPDATE reception_sessions SET dining_party_id=NULL,version=version+1,reply_epoch=reply_epoch+1 WHERE id=old_owner.id;END IF;
  PERFORM dg_native_dining_effect(dining_action_identifier,'dining_parties',p.id);UPDATE dining_parties SET owner_session_id=session_value,created_focus_version=focus_value,version=version+1,access_version=access_version+1,claim_nonce=body->'_ticket'->>'nonce',claim_hash=body->'_ticket'->>'sha256',updated_at=now_value WHERE id=p.id;PERFORM dg_native_dining_touch(meta,dining_action_identifier,p.id,true);
 END CASE;
 INSERT INTO outbox_events VALUES(gen_random_uuid()::text,r.tenant_id,r.workspace_id,party_value,'dining.'||action_value,'mock','{}',now_value,NULL);RETURN dining_action_identifier;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_status(target text,ignore_control boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE o restaurant_orders%ROWTYPE;c restaurant_order_changes%ROWTYPE;active bigint;started bigint;ready bigint;served bigint;
BEGIN
 SELECT * INTO o FROM restaurant_orders WHERE id=target;IF o.status IN('closed','cancelled') THEN RETURN o.status;END IF;IF o.settlement_status='settled' AND dg_native_bill_order_fulfilled(o.id) THEN RETURN 'closed';END IF;IF o.control_mode='human' AND NOT ignore_control THEN RETURN 'needs_attention';END IF;SELECT * INTO c FROM restaurant_order_changes WHERE id=o.pending_change_id;
 IF c.status IN('draft','awaiting_confirmation','confirmed','queued','submitting','submitted') THEN RETURN c.status;ELSIF c.status='unknown' THEN RETURN 'needs_attention';END IF;
 SELECT coalesce(sum(line.quantity-line.cancelled_quantity),0),coalesce(sum(ticket.started_quantity),0),coalesce(sum(ticket.ready_quantity),0),coalesce(sum(ticket.served_quantity),0) INTO active,started,ready,served FROM restaurant_order_lines line JOIN restaurant_kitchen_tickets ticket ON ticket.line_id=line.id WHERE line.order_id=o.id;
 IF active>0 THEN RETURN(CASE WHEN served>=active THEN 'served' WHEN ready>=active THEN 'ready' WHEN started>0 THEN 'preparing' ELSE 'accepted' END);END IF;
 IF EXISTS(SELECT 1 FROM restaurant_order_lines WHERE order_id=o.id) THEN RETURN 'cancelled';END IF;SELECT * INTO c FROM restaurant_order_changes WHERE order_id=o.id ORDER BY sequence DESC LIMIT 1;RETURN(CASE WHEN c.status IN('withdrawn','stale') THEN 'cancelled' WHEN c.status IN('rejected','unknown') THEN 'needs_attention' ELSE 'draft' END);
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_transport_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE record_value text;order_value text;party_value text;restaurant_value text;action _dg_native_dining_actions%ROWTYPE;
BEGIN
 record_value:=CASE WHEN table_value IN('restaurant_order_dispatches','mock_pos_operations') THEN j->>'change_id' WHEN table_value='restaurant_pos_callbacks' THEN j->>'event_id' ELSE j->>'id' END;
 IF table_value='restaurant_orders' THEN order_value:=j->>'id';ELSIF table_value IN('restaurant_order_changes','restaurant_order_lines','restaurant_kitchen_tickets','restaurant_order_events') THEN order_value:=j->>'order_id';ELSE SELECT order_id INTO order_value FROM restaurant_order_changes WHERE id=j->>'change_id';END IF;
 SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_orders WHERE id=order_value;
 SELECT a.* INTO action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions a ON a.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND a.transaction_id=effect.transaction_id AND a.restaurant_id=restaurant_value AND a.resource_id=party_value AND a.kind IN('order_send','order_lookup','order_unknown','order_receipt','order_query','order_mock_fixture','order_mock_remote') ORDER BY a.created_at DESC,a.id DESC LIMIT 1;
 IF action.id IS NULL THEN RETURN false;END IF;IF operation_value='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch and trusted business facts cannot be deleted';END IF;
 IF table_value='restaurant_orders' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['status','version','content_version','pending_change_id','remote_order_id','control_mode','attention_reason','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','content_version','pending_change_id','remote_order_id','control_mode','attention_reason','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'status' NOT IN('submitting','submitted','needs_attention','accepted','draft','cancelled','preparing','ready','served') OR j->>'settlement_status' IS DISTINCT FROM previous->>'settlement_status' OR(j->>'content_version')::bigint NOT BETWEEN(previous->>'content_version')::bigint AND(previous->>'content_version')::bigint+1 OR action.kind<>'order_receipt' AND j-ARRAY['status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','updated_at'] OR action.kind='order_receipt' AND j->>'remote_order_id' IS DISTINCT FROM previous->>'remote_order_id' AND previous->>'remote_order_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport only changes order state or applies the original trusted content once';END IF;
 ELSIF table_value='restaurant_order_changes' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['version','status','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR NOT(action.kind='order_send' AND previous->>'status'='queued' AND j->>'status'='submitting' OR action.kind='order_lookup' AND previous->>'status'='submitting' AND j->>'status'='unknown' OR action.kind='order_unknown' AND previous->>'status' IN('submitting','submitted','unknown') AND j->>'status'='unknown' OR action.kind='order_receipt' AND previous->>'status' IN('submitting','submitted','unknown') AND j->>'status' IN('submitted','accepted','rejected','unknown')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport cannot rewrite draft identity, input or its original confirmation';END IF;
 ELSIF table_value='restaurant_order_dispatches' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['status','version','attempts','lease_token','lease_until','remote_request_id','remote_order_id','last_sequence','error_code','error_message','query_requested','lookups','last_lookup_at','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','attempts','lease_token','lease_until','remote_request_id','remote_order_id','last_sequence','error_code','error_message','query_requested','lookups','last_lookup_at','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'attempts')::bigint<>1 OR j->>'status' NOT IN('submitting','submitted','unknown','accepted','rejected') OR(j->>'last_sequence')::bigint<(previous->>'last_sequence')::bigint OR(previous->>'attempts')::bigint=0 AND NOT(action.kind='order_send' AND previous->>'status'='queued' AND j->>'status'='submitting') OR previous->>'status' IN('accepted','rejected') AND j->>'status' IS DISTINCT FROM previous->>'status' OR action.kind IN('order_query','order_mock_fixture') AND j-ARRAY['version','query_requested','updated_at'] IS DISTINCT FROM previous-ARRAY['version','query_requested','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch attempts and the frozen original request cannot be reset or retargeted';END IF;
 ELSIF table_value='restaurant_order_quotes' THEN
  IF operation_value<>'UPDATE' OR action.kind<>'order_receipt' OR previous->>'status'<>'current' OR j->>'status' NOT IN('accepted','rejected') OR j-'status' IS DISTINCT FROM previous-'status' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Final receipts consume the original quote without changing its deadline or contents';END IF;
 ELSIF table_value='restaurant_inventory_reservations' THEN
  IF operation_value<>'UPDATE' OR action.kind<>'order_receipt' OR previous->>'status'<>'reserved' OR j->>'status' NOT IN('committed','released') OR j-ARRAY['status','updated_at'] IS DISTINCT FROM previous-ARRAY['status','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only trusted final receipts commit or release existing reservations';END IF;
 ELSIF table_value='restaurant_stock_movements' THEN
  IF operation_value<>'INSERT' OR action.kind<>'order_receipt' OR j->>'kind' NOT IN('release','cancel_return') OR(j->>'after_quantity')::bigint<=(j->>'before_quantity')::bigint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stock returns require the trusted original receipt';END IF;
 ELSIF table_value='restaurant_order_lines' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND((j->>'cancelled_quantity')::bigint<>0 OR j->>'created_at'<>action.created_at) OR operation_value='UPDATE' AND(j-'cancelled_quantity' IS DISTINCT FROM previous-'cancelled_quantity' OR(j->>'cancelled_quantity')::bigint<=(previous->>'cancelled_quantity')::bigint OR(j->>'cancelled_quantity')::bigint>(j->>'quantity')::bigint)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accepted line snapshots are immutable except trusted cancelled quantities';END IF;
 ELSIF table_value='restaurant_kitchen_tickets' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND((j->>'started_quantity')::bigint<>0 OR(j->>'ready_quantity')::bigint<>0 OR(j->>'served_quantity')::bigint<>0 OR(j->>'pending_cancel_quantity')::bigint<>0 OR(j->>'version')::bigint<>1 OR j->>'accepted_at'<>action.created_at) OR operation_value='UPDATE' AND(j-ARRAY['pending_cancel_quantity','version','updated_at'] IS DISTINCT FROM previous-ARRAY['pending_cancel_quantity','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'pending_cancel_quantity')::bigint<0)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt creates original kitchen rows without inventing preparation progress';END IF;
 ELSIF table_value='restaurant_pos_callbacks' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND(j->>'created_at'<>action.created_at OR j->>'applied'<>'0' OR j->>'conflict'<>'0') OR operation_value='UPDATE' AND(j-ARRAY['applied','conflict'] IS DISTINCT FROM previous-ARRAY['applied','conflict'] OR previous->>'applied'<>'0' OR previous->>'conflict'<>'0' OR(j->>'applied')::bigint+(j->>'conflict')::bigint<>1)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt payload is immutable and has one terminal local application outcome';END IF;
 ELSIF table_value='mock_pos_operations' THEN
  IF operation_value<>'INSERT' OR action.kind NOT IN('order_mock_remote','order_mock_fixture') OR j->>'outcome' NOT IN('accepted','rejected') OR j->>'sequence'<>'2' OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit local mock facts are append-only and cannot replace a real provider';END IF;
 ELSIF table_value='restaurant_order_events' THEN
  IF operation_value<>'INSERT' OR j->>'actor_id'<>action.actor_id OR j->>'kind'<>action.kind OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport audit retains its actual operation and actor';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported transport effect';END IF;RETURN true;
END;$dg$;


DO $bill_acl$ DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=current_schema() AND p.proname LIKE 'dg_native_bill_%' LOOP EXECUTE 'REVOKE ALL ON FUNCTION '||f.signature||' FROM PUBLIC';END LOOP;END;$bill_acl$;
